function composeWorkflow(workflow, values = {}, { enforceRequired = true, extraSkillIds = [], extraDatabaseIds = [] } = {}) {
  if (!workflow || workflow.type !== 'workflow') throw new Error('请选择一个工作流程。')
  const missing = (workflow.placeholders || [])
    .filter(field => field.required && !String(values[field.key] || '').trim())
    .map(field => field.label)
  if (enforceRequired && missing.length) throw new Error(`请填写：${missing.join('、')}`)
  const prompt = workflow.prompt.replace(/\{([a-zA-Z0-9_-]+)\}/g, (_, key) => {
    const value = String(values[key] || '').trim()
    const field = workflow.placeholders?.find(item => item.key === key)
    return value || (field?.required ? `[${field.label}]` : '未指定（请按综合方式处理）')
  })

  const attached = (extraSkillIds || [])
    .map(itemById)
    .filter(skill => skill?.type === 'skill' && skill.promptFragment)
  const attachedDatabases = (extraDatabaseIds || [])
    .map(itemById)
    .filter(database => database?.type === 'database')
  const additions = [
    attached.length ? `附加技能指导：\n${attached.map(skill => `- 【${skill.name}】${skill.promptFragment}`).join('\n')}` : '',
    attachedDatabases.length ? `研究资源提示：\n${attachedDatabases.map(database => `- 【${database.name}】${database.accessNote}；未确认当前会话具备访问能力前，不得声称已检索。`).join('\n')}` : ''
  ].filter(Boolean)
  const guardedPrompt = `${prompt}\n\n通用科研边界：仅基于已提供材料或已核验来源；不得编造数据、图表、引用、结果、完成状态或文件路径；无法确认时明确标记为待核验。`
  const finalPrompt = additions.length ? `${guardedPrompt}\n\n${additions.join('\n\n')}` : guardedPrompt


  const firstSentence = text => String(text || '').split(/[。；;]/)[0].slice(0, 40)
  const trace = [
    { step: 'workflow', id: workflow.id, label: workflow.name, detail: workflow.description || '' },
    ...(workflow.placeholders || []).map(field => {
      const value = String(values[field.key] || '').trim()
      return {
        step: 'param', id: field.key, label: field.label,
        detail: value || (field.required ? `[${field.label}]` : '未指定（请按综合方式处理）'),
        empty: !value,
      }
    }),
    ...attached.map(skill => ({ step: 'skill', id: skill.id, label: skill.name, detail: firstSentence(skill.promptFragment) })),
    ...attachedDatabases.map(database => ({ step: 'database', id: database.id, label: database.name, detail: firstSentence(database.accessNote) })),
    { step: 'guard', id: 'generic-guard', label: '科研边界', detail: '不得编造；无法确认时标记为待核验' },
  ]
  return {
    prompt: finalPrompt,
    missing,
    attachedSkillIds: attached.map(skill => skill.id),
    attachedDatabaseIds: attachedDatabases.map(database => database.id),
    trace,
  }
}






const FAVORITES_KEY = 'dsh-research-kit:favorites'
const HISTORY_KEY = 'dsh-research-kit:history'
const HISTORY_EVENT = 'dsh-research-kit:history-changed'
const MAX_HISTORY = 20

function safeStorage() {
  try {
    if (typeof localStorage !== 'undefined' && localStorage) return localStorage
  } catch { /* 隐私模式或宿主禁用时降级 */ }
  return null
}

function readStore(key, storage) {
  const store = storage || safeStorage()
  if (!store) return []
  try {
    const raw = JSON.parse(store.getItem(key) || '[]')
    return Array.isArray(raw) ? raw : []
  } catch { return [] }
}

function writeStore(key, value, storage) {
  const store = storage || safeStorage()
  if (!store) return false
  try { store.setItem(key, JSON.stringify(value)); return true } catch { return false }
}

function readIds(key, storage) {
  return readStore(key, storage).filter(id => typeof id === 'string')
}




function readHistoryRows(storage) {
  return readStore(HISTORY_KEY, storage).filter(row => row && typeof row === 'object' && typeof row.id === 'string')
}

function createCatalogStorage({ storage } = {}) {
  const store = storage || safeStorage()
  const listeners = new Set()

  const hasWindow = typeof window !== 'undefined' && !!window
  const notifyHistory = rows => {
    if (hasWindow) {
      try { window.dispatchEvent(new CustomEvent(HISTORY_EVENT, { detail: { key: HISTORY_KEY } })) } catch { /* 事件不可用时忽略 */ }
    }

    for (const callback of listeners) { try { callback(rows) } catch { /* 单个监听者异常不阻断 */ } }
    return rows
  }
  return {
    getFavorites() { return readIds(FAVORITES_KEY, store) },
    toggleFavorite(id) {
      const current = readIds(FAVORITES_KEY, store)
      const next = current.includes(id) ? current.filter(item => item !== id) : [...current, id]
      return writeStore(FAVORITES_KEY, next, store) ? next : current
    },

    getRecents() {
      const seen = new Set()
      const ids = []
      for (const row of readHistoryRows(store)) {
        if (row.id && !seen.has(row.id)) { seen.add(row.id); ids.push(row.id) }
      }
      return ids
    },




    recordHistory(entry) {
      if (!entry?.id) return readHistoryRows(store)
      const summary = String(entry.summary || '').split('\n')[0].trim().slice(0, 80)
      const row = { id: entry.id, name: String(entry.name || ''), summary, at: Date.now() }
      const next = [row, ...readHistoryRows(store).filter(item => item.id !== row.id)].slice(0, MAX_HISTORY)
      writeStore(HISTORY_KEY, next, store)
      return notifyHistory(next)
    },
    getHistory() { return readHistoryRows(store) },
    clearHistory() { writeStore(HISTORY_KEY, [], store); return notifyHistory([]) },
    onHistoryChange(callback) {
      const refresh = () => { try { callback(readHistoryRows(store)) } catch { /* 忽略 */ } }
      const onCustom = event => { if (event?.detail?.key === HISTORY_KEY) refresh() }
      const onStorage = event => { if (event?.key === HISTORY_KEY) refresh() }
      listeners.add(callback)
      if (hasWindow) {
        window.addEventListener(HISTORY_EVENT, onCustom)
        window.addEventListener('storage', onStorage)
      }
      return () => {
        listeners.delete(callback)
        if (hasWindow) {
          window.removeEventListener(HISTORY_EVENT, onCustom)
          window.removeEventListener('storage', onStorage)
        }
      }
    },
    clear() {
      if (!store) return
      try { store.removeItem(FAVORITES_KEY); store.removeItem(HISTORY_KEY) } catch { /* 忽略 */ }
      notifyHistory([])
    }
  }
}




const sessions = new Map()
const MAX_SESSION_STORES = 100

function keyFor(sessionId) { return String(sessionId || 'unscoped') }

function stateFor(sessionId) {
  const key = keyFor(sessionId)
  if (!sessions.has(key)) sessions.set(key, { ids: [], listeners: new Set() })
  const state = sessions.get(key)


  sessions.delete(key)
  sessions.set(key, state)
  while (sessions.size > MAX_SESSION_STORES) {
    const oldest = sessions.entries().next().value
    if (!oldest || oldest[1].listeners.size) break
    sessions.delete(oldest[0])
  }
  return state
}

function createResearchSelectionStore(sessionId) {
  const state = stateFor(sessionId)
  const publish = () => {
    const ids = [...state.ids]
    for (const listener of state.listeners) { try { listener(ids) } catch {} }
    return ids
  }
  return {
    get() { return [...state.ids] },
    set(next) {
      const resolved = typeof next === 'function' ? next([...state.ids]) : next
      state.ids = [...new Set(Array.isArray(resolved) ? resolved.filter(id => typeof id === 'string') : [])]
      return publish()
    },
    toggle(id) {
      return this.set(current => current.includes(id) ? current.filter(item => item !== id) : [...current, id])
    },
    clear() { return this.set([]) },
    subscribe(listener) {
      state.listeners.add(listener)
      return () => state.listeners.delete(listener)
    }
  }
}






const RESEARCH_CONTEXT_KEY = 'dsh-research-kit.research-context.v1'
const RESEARCH_RUNS_KEY = 'dsh-research-kit.research-runs.v1'
const MAX_RESEARCH_RUNS = 500

let contextMemory = { project: '', activeRunId: '' }
const contextListeners = new Set()

function safeStorageGet(key) {
  try { return globalThis.localStorage?.getItem(key) || '' } catch { return '' }
}

function safeStorageSet(key, value) {
  try { globalThis.localStorage?.setItem(key, value) } catch { /* 私有模式下仅保留进程内状态 */ }
}

function normalizeProject(value) {
  return String(value || '').trim().slice(0, 100)
}

function normalizeContext(value) {
  return {
    project: normalizeProject(value?.project),
    activeRunId: String(value?.activeRunId || '').trim(),
  }
}

function readContext() {
  try {
    const raw = safeStorageGet(RESEARCH_CONTEXT_KEY)
    if (raw) contextMemory = normalizeContext(JSON.parse(raw))
  } catch { /* 损坏的偏好不应阻断工作台 */ }
  return { ...contextMemory }
}

function publishContext() {
  const value = { ...contextMemory }
  for (const listener of contextListeners) { try { listener(value) } catch {} }
  return value
}

function currentResearchContext() {
  return readContext()
}

function setResearchContext(next = {}) {
  contextMemory = normalizeContext({ ...readContext(), ...next })
  safeStorageSet(RESEARCH_CONTEXT_KEY, JSON.stringify(contextMemory))
  return publishContext()
}

function setResearchProject(project) {
  const scope = normalizeProject(project)
  const current = currentResearchContext()
  const activeRunId = current.project === scope || listResearchRuns({ project: scope }).some(run => run.id === current.activeRunId)
    ? current.activeRunId : ''
  return setResearchContext({ project: scope, activeRunId })
}

function subscribeResearchContext(listener) {
  contextListeners.add(listener)
  return () => contextListeners.delete(listener)
}

function readRuns() {
  try {
    const rows = JSON.parse(safeStorageGet(RESEARCH_RUNS_KEY) || '[]')
    return Array.isArray(rows) ? rows.filter(row => row && typeof row === 'object')
      .map(row => ({ ...row, workspaceId: workspaceIdForProject(row.project) })) : []
  } catch { return [] }
}

function writeRuns(runs) {
  safeStorageSet(RESEARCH_RUNS_KEY, JSON.stringify(runs.slice(0, MAX_RESEARCH_RUNS)))
  return runs.slice(0, MAX_RESEARCH_RUNS)
}

function runId() {
  return `run-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`
}



function startResearchRun({ project, sessionId = '', workflowId, workflowName, stages = [], status = 'draft', now = Date.now() } = {}) {
  const context = currentResearchContext()
  const resolvedProject = normalizeProject(project === undefined ? context.project : project)
  const run = {
    id: runId(), project: resolvedProject, workspaceId: workspaceIdForProject(resolvedProject), sessionId: String(sessionId || ''),
    workflowId: String(workflowId || ''), workflowName: String(workflowName || ''),
    stages: (Array.isArray(stages) ? stages : []).map(label => String(label)).filter(Boolean).slice(0, 30),
    status: ['draft', 'active', 'waiting_review', 'completed', 'failed'].includes(status) ? status : 'draft',
    createdAt: now, updatedAt: now,
  }
  writeRuns([run, ...readRuns()])
  setResearchContext({ project: resolvedProject, activeRunId: run.id })
  return run
}

function activeResearchRun() {
  const context = currentResearchContext()
  return readRuns().find(run => run.id === context.activeRunId) || null
}

function listResearchRuns({ project, sessionId } = {}) {
  return readRuns().filter(run =>
    (project === undefined || run.project === normalizeProject(project)) &&
    (sessionId === undefined || run.sessionId === String(sessionId || ''))
  )
}



function resumeResearchRun(id, project = currentResearchContext().project) {
  const scope = normalizeProject(project)
  if (currentResearchContext().project !== scope) return null
  const run = listResearchRuns({ project: scope }).find(item => item.id === id)
  if (!run) return null
  setResearchContext({ activeRunId: run.id })
  return run
}

function importResearchRuns(incoming = []) {
  const rows = readRuns()
  const known = new Set(rows.map(row => row.id))
  const added = []
  for (const raw of Array.isArray(incoming) ? incoming : []) {
    if (!raw || typeof raw.id !== 'string' || !raw.id || known.has(raw.id)) continue
    const project = normalizeProject(raw.project)
    added.push({ ...raw, project, workspaceId: workspaceIdForProject(project) })
    known.add(raw.id)
  }
  writeRuns([...rows, ...added])
  return { added: added.length, skipped: incoming.length - added.length }
}

function remapResearchRuns(mappings, { dryRun = false } = {}) {
  const map = new Map(mappings.map(item => [item.from, item.to]))
  const before = readRuns()
  const after = before.map(run => map.has(run.project)
    ? { ...run, project: map.get(run.project), workspaceId: workspaceIdForProject(map.get(run.project)), legacyProject: run.legacyProject || run.project }
    : run)
  const contextBefore = currentResearchContext()
  const contextAfter = map.has(contextBefore.project)
    ? { ...contextBefore, project: map.get(contextBefore.project) } : contextBefore
  if (dryRun) return { before, after, contextBefore, contextAfter }
  writeRuns(after)
  if (map.has(contextBefore.project)) setResearchProject(map.get(contextBefore.project))
  return { before, after, contextBefore, contextAfter: currentResearchContext() }
}

function restoreResearchRuns(snapshot, { validateOnly = false } = {}) {
  const currentRuns = JSON.stringify(readRuns())
  const currentContext = JSON.stringify(currentResearchContext())
  if (![JSON.stringify(snapshot.after), JSON.stringify(snapshot.before)].includes(currentRuns)
    || ![JSON.stringify(snapshot.contextAfter), JSON.stringify(snapshot.contextBefore)].includes(currentContext)) {
    throw new Error('研究运行在整理后已变化，不能自动撤销。')
  }
  if (validateOnly) return true
  writeRuns(snapshot.before)
  setResearchContext(snapshot.contextBefore)
  return true
}


const MAX_QUERIES = 30
const MAX_WORKFLOWS = 30







const evidenceSessions = new Map()
const MAX_EVIDENCE_SESSIONS = 100

function evidenceKeyFor(sessionId) { return String(sessionId || 'unscoped') }

function evidenceStateFor(sessionId) {
  const key = evidenceKeyFor(sessionId)
  if (!evidenceSessions.has(key)) evidenceSessions.set(key, { queries: [], workflows: [], plans: [], listeners: new Set() })
  const state = evidenceSessions.get(key)
  evidenceSessions.delete(key)
  evidenceSessions.set(key, state)
  while (evidenceSessions.size > MAX_EVIDENCE_SESSIONS) {
    const oldest = evidenceSessions.entries().next().value
    if (!oldest || oldest[1].listeners.size) break
    evidenceSessions.delete(oldest[0])
  }
  return state
}

function createEvidenceStore(sessionId) {
  const state = evidenceStateFor(sessionId)
  const get = () => ({ queries: [...state.queries], workflows: [...state.workflows], plans: [...state.plans] })
  const publish = () => {
    const value = get()
    for (const listener of state.listeners) { try { listener(value) } catch {} }
    return value
  }
  const save = next => {

    const source = next && typeof next === 'object' ? next : {}
    state.queries = Array.isArray(source.queries) ? source.queries : []
    state.workflows = Array.isArray(source.workflows) ? source.workflows : []
    state.plans = Array.isArray(source.plans) ? source.plans : []
    return publish()
  }


  const objectRows = value => (Array.isArray(value) ? value : []).filter(item => item && typeof item === 'object')
  return {
    get,
    recordQuery(input) {
      const { databaseId, databaseName, mode = 'direct', sources = [] } = input && typeof input === 'object' ? input : {}
      const current = get()
      const row = { id: `${Date.now()}-${Math.random().toString(36).slice(2, 7)}`, databaseId, databaseName, mode, at: Date.now(), sources: objectRows(sources).slice(0, 8).map(source => ({ id: source.id, title: source.title, url: source.url, meta: source.meta })) }
      return save({ ...current, queries: [row, ...current.queries].slice(0, MAX_QUERIES) })
    },
    recordWorkflow(input) {
      const { id, name, resourceIds = [] } = input && typeof input === 'object' ? input : {}
      const current = get()
      const row = { id, name, resourceIds: [...new Set(Array.isArray(resourceIds) ? resourceIds : [])], at: Date.now() }
      return save({ ...current, workflows: [row, ...current.workflows.filter(item => item?.id !== id)].slice(0, MAX_WORKFLOWS) })
    },
    recordPlan(input) {
      const { workflowId, name, stages = [] } = input && typeof input === 'object' ? input : {}
      const current = get()
      const previous = current.plans.find(plan => plan.id === workflowId)


      const rawStages = Array.isArray(stages) ? stages : []
      const row = { id: workflowId, name, stages: rawStages.map((stage, index) => {
        const label = stage && typeof stage === 'object' ? stage.label : stage

        const before = previous?.stages?.[index]
        return { label, done: before && before.label === label ? before.done : false }
      }), at: Date.now() }
      return save({ ...current, plans: [row, ...current.plans.filter(item => item?.id !== workflowId)] })
    },
    togglePlanStage(planId, index) {
      const current = get()
      return save({ ...current, plans: current.plans.map(plan => plan?.id !== planId ? plan : { ...plan, stages: objectRows(plan.stages).map((stage, i) => i === index ? { ...stage, done: !stage.done } : stage) }) })
    },
    subscribe(listener) { state.listeners.add(listener); return () => state.listeners.delete(listener) },
    clear() { return save({ queries: [], workflows: [], plans: [] }) }
  }
}



