const PROMPTKIT_CLIENT_PATH = '/dsh-research-kit/promptkit-client'





const PROMPTKIT_LOAD_TIMEOUT_MS = 6000
const PROMPTKIT_FETCH_TIMEOUT_MS = 6000

let promptKitNamespace = null
let promptKitPromise = null

function promptKitReady() {
  return Boolean(promptKitNamespace)
}

function getPromptKit() {
  if (!promptKitNamespace) throw new Error('PromptKit 尚未加载。')
  return promptKitNamespace
}


function loadViaScript() {
  return new Promise((resolve, reject) => {
    const script = document.createElement('script')
    script.src = PROMPTKIT_CLIENT_PATH
    script.async = true
    window.__DSH_RESEARCH_REACT__ = React
    let settled = false
    const cleanup = () => {
      if (window.__DSH_RESEARCH_REACT__ === React) delete window.__DSH_RESEARCH_REACT__
      script.remove()
    }
    const fail = error => {
      if (settled) return
      settled = true
      window.clearTimeout(timer)
      cleanup()
      reject(error)
    }
    const timer = window.setTimeout(() => {
      fail(new Error(`<script> 形态 ${PROMPTKIT_LOAD_TIMEOUT_MS / 1000}s 内未返回（宿主可能挂住了这条路由）`))
    }, PROMPTKIT_LOAD_TIMEOUT_MS)
    script.onload = () => {
      if (settled) return
      const loaded = window.__DSH_RESEARCH_PROMPTKIT__
      if (!loaded) {
        fail(new Error('工件已取回，但未导出可用命名空间'))
        return
      }
      settled = true
      window.clearTimeout(timer)
      cleanup()
      resolve(loaded)
    }
    script.onerror = () => fail(new Error('脚本请求失败（onerror）'))
    document.head.appendChild(script)
  })
}






function loadViaFetch() {
  return new Promise((resolve, reject) => {
    if (typeof fetch !== 'function') {
      reject(new Error('当前环境没有 fetch'))
      return
    }
    const controller = typeof AbortController === 'function' ? new AbortController() : null
    let settled = false
    const timer = window.setTimeout(() => {
      if (settled) return
      settled = true
      try { controller?.abort() } catch { /* 取消失败不影响判定 */ }
      reject(new Error(`fetch 形态 ${PROMPTKIT_FETCH_TIMEOUT_MS / 1000}s 内未返回`))
    }, PROMPTKIT_FETCH_TIMEOUT_MS)
    Promise.resolve()
      .then(() => fetch(PROMPTKIT_CLIENT_PATH, { credentials: 'same-origin', ...(controller ? { signal: controller.signal } : {}) }))
      .then(response => {
        if (!response.ok) throw new Error(`fetch 形态 HTTP ${response.status}`)
        return response.text()
      })
      .then(code => {
        if (settled) return
        if (!code) throw new Error('fetch 形态返回空响应')
        window.__DSH_RESEARCH_REACT__ = React
        try {

          new Function(code)()
        } finally {
          if (window.__DSH_RESEARCH_REACT__ === React) delete window.__DSH_RESEARCH_REACT__
        }
        const loaded = window.__DSH_RESEARCH_PROMPTKIT__
        if (!loaded) throw new Error('工件已求值，但未导出可用命名空间')
        settled = true
        window.clearTimeout(timer)
        resolve(loaded)
      })
      .catch(error => {
        if (settled) return
        settled = true
        window.clearTimeout(timer)
        reject(error instanceof Error ? error : new Error(String(error)))
      })
  })
}



function loadPromptKit() {
  if (promptKitNamespace) return Promise.resolve(promptKitNamespace)
  if (promptKitPromise) return promptKitPromise
  if (typeof window === 'undefined' || typeof document === 'undefined') {
    return Promise.reject(new Error('当前环境无法加载 PromptKit 浏览器工件。'))
  }
  const existing = window.__DSH_RESEARCH_PROMPTKIT__
  if (existing) {
    promptKitNamespace = existing
    return Promise.resolve(existing)
  }
  promptKitPromise = (async () => {
    const failures = []
    for (const [label, transport] of [['script', loadViaScript], ['fetch', loadViaFetch]]) {
      try {
        return await transport()
      } catch (error) {
        failures.push(`${label}: ${error?.message || error}`)
      }
    }
    throw new Error(`PromptKit 工件加载失败（${PROMPTKIT_CLIENT_PATH}）—— ${failures.join('；')}`)
  })().then(loaded => {
    promptKitNamespace = loaded
    return loaded
  }, error => {

    promptKitPromise = null
    throw error
  })
  return promptKitPromise
}







const ENTRY_MODE_KEY = 'dsh-research-kit.entry-mode.v1'
const ENTRY_MODE_INLINE = 'inline'
const ENTRY_MODE_FLOATING = 'floating'
const ENTRY_MODE_OPTIONS = [
  { value: ENTRY_MODE_INLINE, label: '输入框内' },
  { value: ENTRY_MODE_FLOATING, label: '悬浮伴生钮' },
]
const ENTRY_MODE_HINTS = {
  [ENTRY_MODE_INLINE]: '在输入框的「科研辅助」中选择「整理当前提问」。回答下方的「回答依据」可查看和保存待核验引用。',
  [ENTRY_MODE_FLOATING]: '右下角可拖拽的悬浮钮，位置自动记忆；旁边恢复「沉淀最近回答」伴生圆钮，与本次改版前的行为一致。',
}

const entryModeListeners = new Set()


function normalizeEntryMode(value) {
  return value === ENTRY_MODE_FLOATING ? ENTRY_MODE_FLOATING : ENTRY_MODE_INLINE
}

function readEntryMode() {
  try {
    return normalizeEntryMode(window.localStorage.getItem(ENTRY_MODE_KEY))
  } catch {
    return ENTRY_MODE_INLINE // 存储不可用（隐私模式等）时用默认形态，不报错
  }
}


function writeEntryMode(value) {
  const mode = normalizeEntryMode(value)
  try { window.localStorage.setItem(ENTRY_MODE_KEY, mode) } catch { /* 写不了也仍然即时生效 */ }
  for (const listener of [...entryModeListeners]) {
    try { listener(mode) } catch { /* 单个订阅者出错不牵连其它 */ }
  }
  return mode
}

function subscribeEntryMode(listener) {
  entryModeListeners.add(listener)
  return () => entryModeListeners.delete(listener)
}

function useEntryMode() {
  const [mode, setMode] = React.useState(readEntryMode)
  React.useEffect(() => subscribeEntryMode(setMode), [])
  return mode
}


function EntryModeSetting() {
  const mode = useEntryMode()
  return h('section', {
    'aria-label': '草稿增强入口',
    'data-research-kit': 'entry-mode-setting',
    style: { display: 'grid', gap: 8, padding: '12px 14px', border: `1px solid ${C.line}`, borderRadius: 12, background: C.surfaceAlt },
  }, [
    h('div', { key: 'head', style: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 10, flexWrap: 'wrap' } }, [
      h('div', { key: 'copy', style: { display: 'grid', gap: 2 } }, [
        h('strong', { key: 'title', style: { fontSize: 13 } }, '草稿增强入口'),
        h('span', { key: 'scope', style: { color: C.muted, fontSize: 12 } }, '本机设置 · 改完即时生效'),
      ]),
      h(Segmented, {
        key: 'segmented', value: mode, options: ENTRY_MODE_OPTIONS, onChange: writeEntryMode, ariaLabel: '草稿增强入口形态',
      }),
    ]),
    h('p', { key: 'hint', style: { margin: 0, color: C.muted, fontSize: 12, lineHeight: 1.6 } }, ENTRY_MODE_HINTS[mode]),
  ])
}



