const DEFAULT_CONSOLE_SECTION = 'home'


function normalizeConsoleSection(value, sections = RESEARCH_CONSOLE_SECTIONS) {
  return sections.some(section => section.id === value) ? value : DEFAULT_CONSOLE_SECTION
}

function findConsoleSection(id, sections = RESEARCH_CONSOLE_SECTIONS) {
  return sections.find(section => section.id === id) || sections[0]
}














const POPOVER_GAP = 8           // 浮层底边与输入卡片顶边的间隙
const POPOVER_TOP_CLEARANCE = 8 // 浮层顶边与滚动区顶边的最小留白
const POPOVER_MAX_HEIGHT = 620  // 上限，避免大屏下浮层过长









function overlayMaxHeight(anchorTop, boundaryTop) {
  const available = Math.round(Number(anchorTop) - Number(boundaryTop) - POPOVER_GAP - POPOVER_TOP_CLEARANCE)
  if (!Number.isFinite(available)) return POPOVER_MAX_HEIGHT
  return Math.max(0, Math.min(POPOVER_MAX_HEIGHT, available))
}


function findScrollport(node) {
  let element = node?.parentElement ?? null
  while (element && element !== document.documentElement) {
    const overflowY = getComputedStyle(element).overflowY
    if (overflowY === 'auto' || overflowY === 'scroll' || overflowY === 'hidden') return element
    element = element.parentElement
  }
  return null
}
















function bodyPortal(node, key) {
  if (node == null) return null
  const container = typeof document === 'undefined' ? undefined : document.body
  const portalable = container != null && container.nodeType === 1 && typeof container.addEventListener === 'function'
  return portalable ? createPortal(node, container, key) : node
}





function supportsSafeInsert(inputActions) {
  return typeof inputActions?.captureInsertion === 'function'
    && typeof inputActions?.insertText === 'function'
}


function canWriteDraft(inputActions) {
  return supportsSafeInsert(inputActions) || typeof inputActions?.setDraft === 'function'
}






function writeDraftText(inputActions, text, { mode = 'insert' } = {}) {
  const value = String(text ?? '')
  if (mode !== 'replace' && supportsSafeInsert(inputActions)) {
    const inserted = inputActions.insertText(value, inputActions.captureInsertion())
    if (inserted === true) return { ok: true, inserted: true }
    if (inserted === false) return { ok: false, inserted: false, stale: true }
  }
  if (typeof inputActions?.setDraft !== 'function') return { ok: false }
  inputActions.setDraft(value)
  return { ok: true, inserted: false, fallback: mode !== 'replace' }
}




function currentMainSessionId(sessions) {
  try {
    const state = sessions?.list?.getSnapshot?.()
    const rows = state?.byId && typeof state.byId === 'object' ? state.byId : {}
    for (const row of Object.values(rows)) {
      if (Number(row?.retainedBy?.mainView ?? 0) > 0 && typeof row?.id === 'string' && row.id) return row.id
    }
  } catch { /* 快照不可读时按「没有当前会话」处理 */ }
  return ''
}









function returnToConversation({ uiWorkspace, uiConversation, sessions, view } = {}) {
  if (typeof uiWorkspace?.openSession !== 'function') return false
  const sessionId = currentMainSessionId(sessions)
  if (!sessionId) return false
  try {
    uiWorkspace.openSession(sessionId)
  } catch { return false }

  try {
    const binding = typeof uiConversation?.binding === 'function' ? uiConversation.binding(sessionId) : null
    if (typeof binding?.activate === 'function') binding.activate(String(view ?? ''))
  } catch { /* 标签选中由宿主持久化状态决定，这里失败不影响导航结果 */ }
  return true
}









function supportsSessionLaunch({ uiWorkspace, conversation } = {}) {
  return typeof uiWorkspace?.startSession === 'function'
    && typeof conversation?.input?.requestDraftInitialization === 'function'
}









function launchResearchSession({ uiWorkspace, conversation } = {}, { prompt, whenDraftExists = 'append' } = {}) {
  const text = String(prompt ?? '')
  if (!text.trim()) return false
  if (!supportsSessionLaunch({ uiWorkspace, conversation })) return false
  try {
    uiWorkspace.startSession(undefined, { prompt: text, whenDraftExists })
    return true
  } catch { return false }
}


function researchMaterialInput({ sessions, conversation }, sessionId) {
  try {
    if (!sessionId) return null
    const binding = sessions?.binding?.(sessionId)
    const input = binding && conversation?.input?.for?.(binding.ctx)
    return typeof input?.addReferences === 'function' && typeof input.canInsertReferences === 'function' ? input : null
  } catch { return null }
}

function insertResearchMaterial(host, sessionId, value) {
  const path = String(value || '').trim()
  const segments = path.split('/')
  if (!path || /[\u0000-\u001f\u007f-\u009f"\\:]/u.test(path)
    || segments.some(part => !part || part === '..') || segments.at(-1) === '.') {
    throw new Error('请输入工作区内的相对文件路径。')
  }
  const input = researchMaterialInput(host, sessionId)
  const ref = /\s/u.test(path) ? `@"${path}"` : `@${path}`
  if (!input?.canInsertReferences() || !input.addReferences([{
    source: 'reference', ref, label: segments.at(-1), appearance: 'file', clipboardText: ref,
  }])) throw new Error('当前会话暂时无法添加文件引用。')
}









const DOWNLOAD_REVOKE_DELAY_MS = 1_000


function canDownload() {
  return typeof document !== 'undefined' && typeof URL !== 'undefined' && typeof Blob !== 'undefined'
}

function downloadBlob(blob, filename, { revokeDelayMs = DOWNLOAD_REVOKE_DELAY_MS } = {}) {
  if (!canDownload()) return false
  const url = URL.createObjectURL(blob)
  const link = document.createElement('a')
  link.href = url
  if (filename) link.download = filename
  link.click()

  const revoke = () => URL.revokeObjectURL(url)
  if (revokeDelayMs > 0) setTimeout(revoke, revokeDelayMs)
  else setTimeout(revoke, 0)
  return true
}

function downloadText(text, type, filename, options) {
  if (!canDownload()) return false
  return downloadBlob(new Blob([text], { type }), filename, options)
}

function downloadJsonFile(text, filename, options) {
  return downloadText(text, 'application/json', filename, options)
}








function indexedDbFactory() {
  try {
    return typeof globalThis !== 'undefined' && globalThis.indexedDB ? globalThis.indexedDB : null
  } catch {
    return null
  }
}

function requestToPromise(request) {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result)
    request.onerror = () => reject(request.error || new Error('IndexedDB 请求失败'))
  })
}



async function withTransaction(db, storeNames, mode, run, {
  errorMessage = 'IndexedDB 事务失败',
  abortMessage = 'IndexedDB 事务被中止',
} = {}) {
  const tx = db.transaction(storeNames, mode)


  const settled = new Promise((resolve, reject) => {
    tx.oncomplete = () => resolve()
    tx.onerror = () => reject(tx.error || new Error(errorMessage))
    tx.onabort = () => reject(tx.error || new Error(abortMessage))
  })
  settled.catch(() => {}) // run 抛错时由这里兜住，避免未处理的拒绝
  const value = await run(tx)
  await settled
  return value
}

function withObjectStore(db, storeName, mode, run) {
  return withTransaction(db, storeName, mode, tx => run(tx.objectStore(storeName)))
}








const CACHE_TTL_MS = 5 * 60_000
const MAX_LISTED_SERVERS = 4


function summarizeHostCapabilities(capabilities) {
  if (!capabilities || typeof capabilities !== 'object') return ''
  const parts = []
  const services = capabilities.services || {}
  const flags = [
    ['Web', services.web], ['Shell', services.shell], ['文件系统', services.fs], ['模型路由', services.llm],
  ].filter(([, on]) => on === true).map(([label]) => label)
  if (flags.length) parts.push(`已装配：${flags.join('、')}`)
  const servers = Array.isArray(capabilities.mcpServers) ? capabilities.mcpServers : []
  if (servers.length) {
    const names = servers.slice(0, MAX_LISTED_SERVERS).map(server => server.toolLoading === 'on-demand' ? `${server.server}（按需加载）` : server.server)
    const more = servers.length > MAX_LISTED_SERVERS ? ` 等 ${servers.length} 台` : ''
    parts.push(`MCP 已连接：${names.join('、')}${more}`)
  } else if (capabilities.toolProbeAvailable) {
    parts.push('MCP：未连接任何服务器')
  }
  if (!parts.length) return ''
  return parts.join('；')
}


let cache = { at: 0, summary: '', promise: null }

function resetHostCapabilitiesCache() {
  cache = { at: 0, summary: '', promise: null }
}

async function fetchHostCapabilitiesSummary({ fetcher, now = Date.now() } = {}) {
  const doFetch = fetcher || (typeof globalThis.fetch === 'function' ? globalThis.fetch.bind(globalThis) : null)
  if (!doFetch) return ''
  if (cache.summary && now() - cache.at < CACHE_TTL_MS) return cache.summary
  if (!cache.promise) {
    cache.promise = (async () => {
      const response = await doFetch('/dsh-research-kit/host-capabilities')
      if (!response.ok) return ''
      const body = await response.json().catch(() => null)
      return body?.ok ? summarizeHostCapabilities(body.capabilities) : ''
    })()
  }
  try {
    const summary = await cache.promise
    if (summary) cache = { at: now(), summary, promise: null }
    else cache.promise = null
    return summary
  } catch {
    cache.promise = null
    return ''
  }
}


