for (const [key, messages] of Object.entries(MESSAGE_PAIRS)) {
  if (messages.length !== SUPPORTED_LOCALES.length || messages.some((message) => typeof message !== 'string')) {
    throw new Error(`Incomplete Archify i18n tuple ${JSON.stringify(key)}`);
  }
}

const CATALOGS = Object.fromEntries(SUPPORTED_LOCALES.map((locale, index) => [
  locale,
  Object.fromEntries(Object.entries(MESSAGE_PAIRS).map(([key, pair]) => [key, pair[index]])),
]));

function resolveLocale(locale) {
  return SUPPORTED_LOCALES.includes(locale) ? locale : DEFAULT_LOCALE;
}

function formatMessage(template, values = {}) {
  return String(template).replace(/\{([a-zA-Z0-9_]+)\}/g, (match, key) => (
    Object.hasOwn(values, key) ? String(values[key]) : match
  ));
}

function translateMessage(locale, key, values = {}) {
  const resolved = resolveLocale(locale);
  if (!Object.hasOwn(CATALOGS[resolved], key)) {
    throw new Error(`Missing Archify i18n message ${JSON.stringify(key)} for ${resolved}`);
  }
  return formatMessage(CATALOGS[resolved][key], values);
}

function translateCount(locale, key, count, values = {}) {
  const suffix = count === 1 ? 'one' : 'other';
  return translateMessage(locale, `${key}.${suffix}`, { ...values, count });
}

function viewerCatalog(locale) {
  const resolved = resolveLocale(locale);
  return Object.fromEntries(Object.entries(CATALOGS[resolved]).filter(([key]) => key.startsWith('viewer.')));
}

function localizeTemplate(template, locale) {
  return template.replace(/\{\{i18n:([a-zA-Z0-9_.-]+)\}\}/g, (_match, key) => escapeHtml(translateMessage(locale, key)));
}

function catalogKeys() {
  return Object.keys(MESSAGE_PAIRS);
}










const KIND_ROLE = {
  workflow: 'backend', finding: 'frontend', file: 'cloud',
  skill: 'messagebus', database: 'database',
  boundary: 'security', guard: 'security',
  params: 'external', step: 'external',
}
const KIND_GLYPH = { workflow: '▶', params: '✎', skill: '✦', database: '⛁', boundary: '⚑', guard: '⚑', step: '·', file: '▤', finding: '✳' }
const GLYPH_FONT = 9.5
const LABEL_FONT = 11
const NOTE_FONT = 9
const LINE_H = 14
const NOTE_LINE_H = 11.5
const PAD_X = 10
const HEADER_H = 15
const PAD_BOTTOM = 8

function archifyKindRole(kind) {
  return KIND_ROLE[kind] || 'external'
}

function esc(text) {
  return String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
}

function scriptJson(value) {
  return JSON.stringify(value).replaceAll('<', '\\u003c').replaceAll('>', '\\u003e').replaceAll('&', '\\u0026')
}


function charWidth(ch, fontSize) {
  const wide = /[\u1100-\u115F\u2E80-\uA4CF\uAC00-\uD7A3\uF900-\uFAFF\uFE30-\uFE6F\uFF00-\uFF60\uFFE0-\uFFE6]/.test(ch)
  return (wide ? 1.0 : 0.56) * fontSize
}

function textWidth(text, fontSize) {
  let width = 0
  for (const ch of String(text)) width += charWidth(ch, fontSize)
  return width
}


function wrapByWidth(text, fontSize, maxWidth, maxLines) {
  const source = String(text ?? '')
  if (!source) return []
  const lines = []
  let line = ''
  for (const ch of source) {
    if (line && textWidth(line + ch, fontSize) > maxWidth) {
      lines.push(line)
      line = ch
      if (lines.length === maxLines) break
    } else {
      line += ch
    }
  }
  if (lines.length < maxLines && line) lines.push(line)
  const consumed = lines.join('').length
  if (consumed < source.length && lines.length) {
    let last = lines[lines.length - 1]
    while (last && textWidth(last + '…', fontSize) > maxWidth) last = last.slice(0, -1)
    lines[lines.length - 1] = last + '…'
  }
  return lines
}


function archifyNodeSize(node) {
  const maxTextWidth = 132
  const labelLines = wrapByWidth(node.label, LABEL_FONT, maxTextWidth, 2)
  const noteLines = node.note ? wrapByWidth(node.note, NOTE_FONT, maxTextWidth - 6, 2) : []
  const contentWidth = Math.max(
    74,
    ...labelLines.map(line => textWidth(line, LABEL_FONT)),
    ...noteLines.map(line => textWidth(line, NOTE_FONT)),
  )
  const width = Math.max(Number(node.w) || 0, Math.ceil(contentWidth) + PAD_X * 2 + 6, 124)
  const height = Math.max(
    Number(node.h) || 0,
    Math.ceil(HEADER_H + labelLines.length * LINE_H + (noteLines.length ? noteLines.length * NOTE_LINE_H + 4 : 0) + PAD_BOTTOM),
    42,
  )
  return { w: width, h: height, labelLines, noteLines }
}


function archifyLayoutRow(nodes, { y = 60, gap = 46, x = 40 } = {}) {
  let cursor = x
  return (nodes || []).map(node => {
    const placed = { ...node, x: cursor, y }
    cursor += archifyNodeSize(placed).w + gap
    return placed
  })
}


function archifyEdgeGeometry(nodes, edges) {
  const byId = new Map(nodes.map(n => [n.id, n]))
  const sizeOf = n => {
    const size = archifyNodeSize(n)
    return [size.w, size.h]
  }
  return edges.map((edge, index) => {
    const a = byId.get(edge.from), b = byId.get(edge.to)
    if (!a || !b) return null
    const [aw, ah] = sizeOf(a), [bw, bh] = sizeOf(b)
    const acx = a.x + aw / 2, acy = a.y + ah / 2, bcx = b.x + bw / 2, bcy = b.y + bh / 2
    const dx = bcx - acx, dy = bcy - acy
    const clamp = (cx, cy, hw, hh, direction = 1) => {
      if (dx === 0 && dy === 0) return [cx, cy]
      const t = Math.min(dx !== 0 ? hw / Math.abs(dx) : Infinity, dy !== 0 ? hh / Math.abs(dy) : Infinity)
      return [cx + direction * dx * t, cy + direction * dy * t]
    }
    const [x1, y1] = clamp(acx, acy, aw / 2 + 4, ah / 2 + 4)
    const [x2, y2] = clamp(bcx, bcy, bw / 2 + 7, bh / 2 + 7, -1)
    const mx1 = x1 + (x2 - x1) * 0.42, my1 = y1 + (y2 - y1) * 0.08
    const mx2 = x1 + (x2 - x1) * 0.58, my2 = y1 + (y2 - y1) * 0.92
    return {
      ...edge, index,
      d: `M ${Math.round(x1)} ${Math.round(y1)} C ${Math.round(mx1)} ${Math.round(my1)}, ${Math.round(mx2)} ${Math.round(my2)}, ${Math.round(x2 - Math.sign(dx || 0) * 8)} ${Math.round(y2 - Math.sign(dy || 0) * 8)}`,
    }
  }).filter(Boolean)
}



function buildArchifySvg({ nodes, edges, title, subtitle = '', locale = 'zh-CN', preset = 'classic', animation = 'trace', metrics = {} }) {
  const metricName = { workflows: '工作流', skills: '技能', databases: '数据源', families: '流程族' }
  const sized = nodes.map(n => {
    let suffix = ''
    for (const c of n.computed || []) {
      if (metrics[c.metric] != null) suffix += ` (${metricName[c.metric] || c.metric} ${metrics[c.metric]})`
    }
    const withLabel = { ...n, label: String(n.label) + suffix }
    return { ...withLabel, ...archifyNodeSize(withLabel) }
  })
  const geo = archifyEdgeGeometry(sized, edges)
  const svgAttrs = [
    'role="img"', `lang="${esc(resolveLocale(locale))}"`,
    'aria-labelledby="archify-diagram-title archify-diagram-description"',
    animation === 'trace' ? 'data-animation="trace"' : '',
    `data-preset="${esc(preset)}"`, 'data-quality-profile="standard"',
  ].filter(Boolean).join(' ')
  const parts = []
  parts.push(`<title id="archify-diagram-title">${esc(title)}</title>`)
  parts.push(`<desc id="archify-diagram-description">${esc(subtitle)}</desc>`)
  geo.forEach(edge => {
    const attrs = [
      `id="edge-${esc(edge.id)}"`,
      `data-edge-id="${esc(edge.id)}"`,
      `data-edge-from="${esc(edge.from)}"`,
      `data-edge-to="${esc(edge.to)}"`,
      edge.label ? ` data-edge-label="${esc(edge.label)}"` : '',
      `data-edge-key="${esc(edge.index)}"`,
    ].join('')
    const animate = animation === 'trace' ? ` data-animate="edge" style="--step:${edge.index}"` : ''
    parts.push(`<path ${attrs}${animate} d="${edge.d}" class="a-default" stroke-width="1.6" fill="none" marker-end="url(#arrowhead)"/>`)
  })
  sized.forEach((n, index) => {
    const role = archifyKindRole(n.kind)
    const animate = animation === 'trace' ? ` data-animate="node" style="--step:${index}"` : ''
    const aria = `${n.label}${n.note ? '，' + n.note : ''}`
    const labelTop = n.y + HEADER_H + LABEL_FONT
    parts.push(`<g id="node-${esc(n.id)}" data-node-id="${esc(n.id)}" data-node-label="${esc(n.label)}" data-node-kind="${esc(n.kind)}" tabindex="0" role="button" aria-label="${esc(aria)}" aria-pressed="false"${animate}>`)
    parts.push(`<title>${esc(n.label)}${n.note ? ' · ' + esc(n.note) : ''}</title>`)
    parts.push(`<rect x="${n.x}" y="${n.y}" width="${n.w}" height="${n.h}" rx="7" class="c-mask"/>`)
    parts.push(`<rect x="${n.x}" y="${n.y}" width="${n.w}" height="${n.h}" rx="7" class="c-${role}"${animate} stroke-width="1.5"/>`)
    parts.push(`<text x="${n.x + PAD_X}" y="${n.y + 12}" class="t-muted" font-size="${GLYPH_FONT}">${esc((KIND_GLYPH[n.kind] || '·') + ' ' + (index + 1))}</text>`)
    n.labelLines.forEach((line, li) => {
      parts.push(`<text data-node-label="" x="${n.x + PAD_X}" y="${Math.round(labelTop + li * LINE_H)}" class="t-primary" font-size="${LABEL_FONT}" font-weight="600">${esc(line)}</text>`)
    })
    if (n.noteLines.length) {
      const noteTop = labelTop + n.labelLines.length * LINE_H + 2
      n.noteLines.forEach((line, li) => {
        parts.push(`<text data-detail="context" x="${n.x + PAD_X}" y="${Math.round(noteTop + li * NOTE_LINE_H)}" class="t-muted" font-size="${NOTE_FONT}">${esc(line)}</text>`)
      })
    }
    if (n.source) parts.push(`<text x="${n.x + n.w - 7}" y="${n.y + n.h - 6}" class="t-muted" font-size="8.5" text-anchor="end">SRC</text>`)
    parts.push(`</g>`)
  })
  const canvasW = Math.max(...sized.map(n => n.x + n.w), 320) + 40
  const canvasH = Math.max(...sized.map(n => n.y + n.h), 160) + 40
  return `<svg ${svgAttrs} xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${Math.round(canvasW)} ${Math.round(canvasH)}">\n        ${parts.join('\n        ')}\n      </svg>`
}


function archifyGuidedViews(routes, edges) {
  const byId = new Map((edges || []).map(e => [e.id, e]))
  return (Array.isArray(routes) ? routes : []).slice(0, 5).map(route => {
    const focus = []
    for (const edgeId of route.edgeIds || []) {
      const e = byId.get(edgeId)
      if (!e) continue
      if (!focus.includes(e.from)) focus.push(e.from)
      if (!focus.includes(e.to)) focus.push(e.to)
    }
    const view = { id: route.id, label: String(route.label || route.id).slice(0, 48), focus }
    if (route.note) view.note = String(route.note).slice(0, 140)
    return view
  }).filter(view => view.focus.length >= 1)
}


const SVG_SLOT_RE = /      <!-- ARCHIFY:SVG_SLOT_START -->[\s\S]*?      <!-- ARCHIFY:SVG_SLOT_END -->/
const CARDS_SLOT_RE = /    <!-- ARCHIFY:CARDS_SLOT_START -->[\s\S]*?    <!-- ARCHIFY:CARDS_SLOT_END -->/
const SUBTITLE_SLOT_RE = /^([ \t]*)<p class="subtitle">\[Subtitle description\]<\/p>[ \t]*(\r?\n)?/m
const GUIDED_VIEWS_PLACEHOLDER = '<!-- ARCHIFY:GUIDED_VIEWS_DATA -->'
const I18N_PLACEHOLDER = '    <!-- ARCHIFY:I18N_DATA -->'

function archifyApplyTemplate({ template, title, subtitle, svg, cards, locale = 'zh-CN', visualPreset = 'classic', guidedViews = [] }) {
  if (!SVG_SLOT_RE.test(template)) throw new Error('archify-adapter: 模板缺少 SVG_SLOT 哨兵')
  if (!CARDS_SLOT_RE.test(template)) throw new Error('archify-adapter: 模板缺少 CARDS_SLOT 哨兵')
  const resolvedLocale = resolveLocale(locale)
  const localized = localizeTemplate(template, resolvedLocale)


  const i18nData = `    <script id="archify-i18n-data" type="application/json">${scriptJson({ locale: resolvedLocale, messages: viewerCatalog(resolvedLocale) })}</script>`
  const withI18n = localized.includes(I18N_PLACEHOLDER)
    ? localized.replace(I18N_PLACEHOLDER, () => i18nData)
    : localized.replace(GUIDED_VIEWS_PLACEHOLDER, () => `${i18nData}\n    ${GUIDED_VIEWS_PLACEHOLDER}`)
  const cardList = Array.isArray(cards) ? cards : []
  const cardsMarkup = `    <!-- Info Cards -->
    <div class="cards">
${cardList.map(card => `      <div class="card">
        <div class="card-header">
          <div class="card-dot ${esc(card.dot)}"></div>
          <h3>${esc(card.title)}</h3>
        </div>
        <ul>
${card.items.map(item => `          <li>&bull; ${esc(item)}</li>`).join('\n')}
        </ul>
      </div>`).join('\n\n')}
    </div>`
  const renderedSubtitle = subtitle && String(subtitle).trim()
    ? `<p class="subtitle">${esc(subtitle)}</p>`
    : ''
  return withI18n
    .replace('<html lang="en" data-theme="dark" data-preset="[VISUAL PRESET]">', () => `<html lang="${esc(resolvedLocale)}" data-theme="dark" data-preset="${esc(visualPreset)}">`)
    .replace('<title>[PROJECT NAME] Architecture Diagram</title>', () => `<title>${esc(title)}</title>`)
    .replace('<h1>[PROJECT NAME] Architecture</h1>', () => `<h1>${esc(title)}</h1>`)
    .replace(SUBTITLE_SLOT_RE, () => renderedSubtitle)
    .replace(SVG_SLOT_RE, () => svg)
    .replace(CARDS_SLOT_RE, () => cardsMarkup)
    .replace(GUIDED_VIEWS_PLACEHOLDER, () => `<script id="archify-guided-views-data" type="application/json">${scriptJson(guidedViews)}</script>`)
}












const DB_NAME = 'dsh-research-kit-evidence'



const DB_VERSION = 7
const STORE = 'evidence'
const LINKS_STORE = 'assetEvidenceLinks'
const ORGANIZER_STORE = 'projectOrganizer'
const CLAIMS_STORE = 'researchClaims'
const LEDGER_STORE = 'researchLedger'
const WORKSPACES_STORE = 'researchWorkspaces'

const MAX_LINKS = 500
const PROJECT_KEY = 'dsh-research-kit.evidence.project'



function readStoredProject() {
  try { return globalThis.localStorage?.getItem(PROJECT_KEY) || '' } catch { return '' }
}

function writeStoredProject(value) {
  try { globalThis.localStorage?.setItem(PROJECT_KEY, value) } catch { /* 不可用则仅进程内生效 */ }
}




function evidenceVaultRows(value) {
  return (Array.isArray(value) ? value : []).filter(item => item && typeof item === 'object')
}

function sortBySavedAt(rows) {
  return evidenceVaultRows(rows).sort((a, b) => (b.savedAt || 0) - (a.savedAt || 0))
}

function withWorkspaceIdentity(rows) {
  return evidenceVaultRows(rows).map(item => item.workspaceId === workspaceIdForProject(item.project)
    ? item : { ...item, workspaceId: workspaceIdForProject(item.project) })
}

function createEvidenceVaultStore() {
  let dbPromise = null
  let degraded = false
  let memory = []
  let activeProject = null
  let memoryOrganizerJournal = null
  let memoryResearchClaims = []
  let memoryResearchLedger = []
  let memoryWorkspaces = []

  const connect = () => {
    if (degraded) return Promise.resolve(null)
    if (dbPromise) return dbPromise
    const factory = indexedDbFactory()
    if (!factory) { degraded = true; return Promise.resolve(null) }
    dbPromise = new Promise(resolve => {
      let request
      try { request = factory.open(DB_NAME, DB_VERSION) } catch { degraded = true; resolve(null); return }
      request.onupgradeneeded = () => {
        const db = request.result

        if (!db.objectStoreNames.contains(STORE)) {
          const store = db.createObjectStore(STORE, { keyPath: 'id' })
          store.createIndex('savedAt', 'savedAt')
          store.createIndex('project', 'project')
          store.createIndex('status', 'status')
        }
        const evidenceStore = request.transaction?.objectStore(STORE)
        if (evidenceStore && !evidenceStore.indexNames.contains('projectSavedAtId')) evidenceStore.createIndex('projectSavedAtId', ['project', 'savedAt', 'id'])
        if (evidenceStore && !evidenceStore.indexNames.contains('savedAtId')) evidenceStore.createIndex('savedAtId', ['savedAt', 'id'])
        if (!db.objectStoreNames.contains(LINKS_STORE)) {
          const links = db.createObjectStore(LINKS_STORE, { keyPath: 'id' })
          links.createIndex('assetId', 'assetId')
          links.createIndex('evidenceId', 'evidenceId')
          links.createIndex('project', 'project')
        }
        if (!db.objectStoreNames.contains(ORGANIZER_STORE)) db.createObjectStore(ORGANIZER_STORE, { keyPath: 'id' })
        if (!db.objectStoreNames.contains(CLAIMS_STORE)) {
          const claims = db.createObjectStore(CLAIMS_STORE, { keyPath: 'id' })
          claims.createIndex('project', 'project')
        }
        if (!db.objectStoreNames.contains(LEDGER_STORE)) {
          const ledger = db.createObjectStore(LEDGER_STORE, { keyPath: 'id' })
          ledger.createIndex('project', 'project')
        }
        if (!db.objectStoreNames.contains(WORKSPACES_STORE)) db.createObjectStore(WORKSPACES_STORE, { keyPath: 'id' })
      }
      request.onsuccess = () => { if (!request.result) degraded = true; resolve(request.result || null) }
      request.onerror = () => { degraded = true; resolve(null) }
      request.onblocked = () => { degraded = true; resolve(null) }
    })
    return dbPromise
  }


  const withStore = async (mode, run, storeName = STORE) => {
    const db = await connect()
    if (!db) return undefined
    return withObjectStore(db, storeName, mode, run)
  }


  let memoryLinks = []

  const readAll = async () => {
    const rows = await withStore('readonly', store => requestToPromise(store.getAll()))
    return sortBySavedAt(withWorkspaceIdentity(Array.isArray(rows) ? rows : memory))
  }



  const readProject = async project => {
    if (typeof project !== 'string') return readAll()
    const rows = await withStore('readonly', store => requestToPromise(store.index('project').getAll(project)))
    return sortBySavedAt(withWorkspaceIdentity(Array.isArray(rows) ? rows : memory.filter(item => (item.project || '') === project)))
  }

  const scanEvidence = async (project, cursor, visit) => {
    const db = await connect()
    if (db && typeof globalThis.IDBKeyRange !== 'undefined') {
      return withStore('readonly', store => new Promise((resolve, reject) => {
        const scoped = typeof project === 'string'
        const index = store.index(scoped ? 'projectSavedAtId' : 'savedAtId')
        const lower = scoped ? [project, 0, ''] : [0, '']
        const upper = cursor || (scoped ? [project, Number.MAX_SAFE_INTEGER, '\uffff'] : [Number.MAX_SAFE_INTEGER, '\uffff'])
        const request = index.openCursor(IDBKeyRange.bound(lower, upper, false, Boolean(cursor)), 'prev')
        request.onerror = () => reject(request.error || new Error('证据分页读取失败。'))
        request.onsuccess = () => {
          const row = request.result
          if (!row || visit(row.value, row.key) === false) { resolve(); return }
          row.continue()
        }
      }))
    }
    const rows = (await readProject(project)).sort((a, b) => (b.savedAt || 0) - (a.savedAt || 0) || (String(a.id) < String(b.id) ? 1 : String(a.id) > String(b.id) ? -1 : 0))
    for (const row of rows) {
      const key = typeof project === 'string' ? [project, row.savedAt || 0, row.id] : [row.savedAt || 0, row.id]
      if (cursor && (key.at(-2) > cursor.at(-2) || (key.at(-2) === cursor.at(-2) && key.at(-1) >= cursor.at(-1)))) continue
      if (visit(row, key) === false) break
    }
  }


  const inProject = (rows, project) =>
    (typeof project === 'string' ? rows.filter(item => (item.project || '') === project) : rows)

  return {
    isDegraded: () => degraded,

    async readOrganizerJournal() {
      const row = await withStore('readonly', store => requestToPromise(store.get('last')), ORGANIZER_STORE)
      return row === undefined ? memoryOrganizerJournal : row || null
    },
    async writeOrganizerJournal(value) {
      const row = { ...value, id: 'last' }
      const written = await withStore('readwrite', store => requestToPromise(store.put(row)), ORGANIZER_STORE)
      if (written === undefined) memoryOrganizerJournal = row
      return row
    },


    async cacheResearchClaims(rows) {
      const result = await withStore('readwrite', store => Promise.all(rows.map(row => requestToPromise(store.put(row)))), CLAIMS_STORE)
      if (result === undefined) {
        const ids = new Set(rows.map(row => row.id))
        memoryResearchClaims = [...rows, ...memoryResearchClaims.filter(row => !ids.has(row.id))]
      }
    },
    async listResearchClaims({ project } = {}) {
      const rows = await withStore('readonly', store => requestToPromise(
        typeof project === 'string' ? store.index('project').getAll(project) : store.getAll()), CLAIMS_STORE)
      return withWorkspaceIdentity(Array.isArray(rows) ? rows : memoryResearchClaims.filter(item => project === undefined || item.project === project))
        .sort((a, b) => (b.updatedAt || 0) - (a.updatedAt || 0))
    },
    async saveResearchClaim(input) {
      const claim = normalizeResearchClaim(input)
      const evidenceIds = new Set((await readAll()).map(item => item.id))
      if (claim.links.some(item => !evidenceIds.has(item.evidenceId))) throw new Error('论断关联了不存在的证据，请刷新后重试。')
      const result = await withStore('readwrite', store => requestToPromise(store.put(claim)), CLAIMS_STORE)
      if (result === undefined) memoryResearchClaims = [claim, ...memoryResearchClaims.filter(item => item.id !== claim.id)]
      return claim
    },

    async listResearchLedger({ project, kind, runId } = {}) {
      const rows = await withStore('readonly', store => requestToPromise(
        typeof project === 'string' ? store.index('project').getAll(project) : store.getAll()), LEDGER_STORE)
      return withWorkspaceIdentity(Array.isArray(rows) ? rows : memoryResearchLedger)
        .filter(item => (project === undefined || item.project === project)
          && (kind === undefined || item.kind === kind) && (runId === undefined || item.runId === runId))
        .sort((a, b) => (b.at || 0) - (a.at || 0))
    },
    async saveResearchLedgerEvent(input) {
      const event = normalizeResearchLedgerEvent(input)
      if (event.kind === 'screening' && !(await readAll()).some(item => item.id === event.evidenceId)) {
        throw new Error('筛选记录关联了不存在的证据。')
      }
      const result = await withStore('readwrite', store => requestToPromise(store.put(event)), LEDGER_STORE)
      if (result === undefined) memoryResearchLedger = [event, ...memoryResearchLedger.filter(item => item.id !== event.id)]
      return event
    },



    async listWorkspaces({ includeArchived = false } = {}) {
      const persisted = await withStore('readonly', store => requestToPromise(store.getAll()), WORKSPACES_STORE)
      const records = Array.isArray(persisted) ? persisted : memoryWorkspaces
      const byKey = new Map(records.map(row => [row.projectKey, workspaceForProject(row.projectKey, row)]))
      for (const projectKey of await this.listProjects()) {
        if (!byKey.has(projectKey)) byKey.set(projectKey, workspaceForProject(projectKey))
      }
      return [...byKey.values()].filter(row => row && (includeArchived || !row.archived))
        .sort((a, b) => a.name.localeCompare(b.name, 'zh-CN'))
    },
    async createWorkspace(inputName) {
      const name = normalizeWorkspaceName(inputName)
      const all = await this.listWorkspaces({ includeArchived: true })
      if (all.some(row => row.name === name && !row.archived)) throw new Error('同名课题已存在，请直接选择。')
      if (all.some(row => row.projectKey === name)) throw new Error('该名称已被旧项目占用，请先整理或重命名。')
      const now = Date.now()
      const row = workspaceForProject(name, { name, origin: 'user', createdAt: now, updatedAt: now })
      const result = await withStore('readwrite', store => requestToPromise(store.put(row)), WORKSPACES_STORE)
      if (result === undefined) memoryWorkspaces = [...memoryWorkspaces, row]
      return row
    },
    async renameWorkspace(projectKey, inputName) {
      const name = normalizeWorkspaceName(inputName)
      const all = await this.listWorkspaces({ includeArchived: true })
      const current = all.find(row => row.projectKey === projectKey)
      if (!current) throw new Error('找不到该课题。')
      if (all.some(row => row.projectKey !== projectKey && row.name === name && !row.archived)) throw new Error('同名课题已存在。')
      const row = workspaceForProject(projectKey, { ...current, name, updatedAt: Date.now() })
      const result = await withStore('readwrite', store => requestToPromise(store.put(row)), WORKSPACES_STORE)
      if (result === undefined) memoryWorkspaces = [row, ...memoryWorkspaces.filter(item => item.id !== row.id)]
      return row
    },
    async setWorkspaceArchived(projectKey, archived) {
      const all = await this.listWorkspaces({ includeArchived: true })
      const current = all.find(row => row.projectKey === projectKey)
      if (!current) throw new Error('找不到该课题。')
      const row = workspaceForProject(projectKey, { ...current, archived: archived === true, updatedAt: Date.now() })
      const result = await withStore('readwrite', store => requestToPromise(store.put(row)), WORKSPACES_STORE)
      if (result === undefined) memoryWorkspaces = [row, ...memoryWorkspaces.filter(item => item.id !== row.id)]
      return row
    },
    async importWorkspaces(inputs = []) {
      if (!Array.isArray(inputs)) throw new Error('课题备份格式无效。')
      const persisted = await withStore('readonly', store => requestToPromise(store.getAll()), WORKSPACES_STORE)
      const existing = Array.isArray(persisted) ? persisted : memoryWorkspaces
      const knownKeys = new Set(existing.map(item => item.projectKey))
      const names = new Map((await this.listWorkspaces({ includeArchived: true }))
        .filter(item => !item.archived).map(item => [item.name, item.projectKey]))
      const rows = []
      for (const input of inputs) {
        const projectKey = String(input?.projectKey || '').trim()
        if (!projectKey || projectKey.length > 120) throw new Error('课题备份的项目键无效。')
        const name = normalizeWorkspaceName(input?.name)
        if (input.id !== workspaceIdForProject(projectKey)) throw new Error('课题备份 ID 与项目键不一致。')
        if (knownKeys.has(projectKey)) continue // 增量恢复不覆盖现有显示名或归档状态。
        if (!input.archived && names.has(name) && names.get(name) !== projectKey) throw new Error(`课题显示名「${name}」与现有课题冲突。`)
        const row = workspaceForProject(projectKey, {
          name, archived: input.archived === true,
          origin: input.origin === 'user' ? 'user' : 'legacy',
          createdAt: input.createdAt, updatedAt: input.updatedAt,
        })
        rows.push(row); knownKeys.add(projectKey)
        if (!row.archived) names.set(row.name, row.projectKey)
      }
      if (!rows.length) return 0
      const result = await withStore('readwrite', store => Promise.all(rows.map(row => requestToPromise(store.put(row)))), WORKSPACES_STORE)
      if (result === undefined) memoryWorkspaces = [...rows, ...memoryWorkspaces]
      return rows.length
    },


    getActiveProject() {
      if (activeProject === null) activeProject = readStoredProject()
      return activeProject
    },
    setActiveProject(project) {
      activeProject = String(project || '')
      writeStoredProject(activeProject)
      return activeProject
    },

    async getMany(ids = []) {
      const values = await withStore('readonly', store => Promise.all(ids.map(id => requestToPromise(store.get(id)))))
      return withWorkspaceIdentity(Array.isArray(values) ? values : memory.filter(row => ids.includes(row.id)))
    },
    async listPage({ project, query = '', filter = 'all', limit = 50, cursor = null, screenedIds = null } = {}) {
      const size = Math.max(1, Math.min(100, Math.floor(Number(limit) || 50)))
      const scope = JSON.stringify([project ?? null, String(query), filter, screenedIds || null])
      if (cursor && (cursor.scope !== scope || !Array.isArray(cursor.key))) throw new Error('分页条件已变化，请返回第一页。')
      const rows = []; let lastKey = null; let hasMore = false
      const screened = screenedIds ? new Set(screenedIds) : null
      await scanEvidence(project, cursor?.key, (row, key) => {
        if (!row || typeof row !== 'object' || (screened && screened.has(row.id)) || !filterEvidence([row], { query, filter }).length) return
        if (rows.length === size) { hasMore = true; return false }
        rows.push(row); lastKey = key
      })
      return { rows: withWorkspaceIdentity(rows), nextCursor: hasMore ? { scope, key: lastKey } : null }
    },
    async evidenceSummary({ project } = {}) {
      const counts = statusCounts([])
      await scanEvidence(project, null, row => {
        if (!row || typeof row !== 'object') return
        counts.all++; counts[row.status || 'unverified'] = (counts[row.status || 'unverified'] || 0) + 1
      })
      return counts
    },
    async list({ project } = {}) {
      return readProject(project)
    },


    async listProjects() {
      const db = await connect()
      if (db && typeof globalThis.IDBKeyRange !== 'undefined') {
        const projects = await withStore('readonly', store => new Promise((resolve, reject) => {
          const rows = []; const request = store.index('project').openKeyCursor(null, 'nextunique')
          request.onerror = () => reject(request.error || new Error('课题列表读取失败。'))
          request.onsuccess = () => { const cursor = request.result; if (!cursor) { resolve(rows); return }; if (cursor.key) rows.push(cursor.key); cursor.continue() }
        }))
        return projects.sort((a, b) => a.localeCompare(b, 'zh-CN'))
      }
      const rows = await readAll()
      return [...new Set(rows.map(item => item.project).filter(Boolean))].sort((a, b) => a.localeCompare(b, 'zh-CN'))
    },


    async save(input, { onDuplicate = 'reject' } = {}) {

      const entry = normalizeEvidenceEntry(input)
      const existing = await readProject(entry.project)
      const duplicate = findDuplicate(existing, entry)
      if (duplicate && onDuplicate === 'reject') {
        const error = new Error(`该来源已在本项目证据库中：「${duplicate.title}」。`)
        error.code = 'DUPLICATE'
        error.duplicate = duplicate
        throw error
      }

      const finalEntry = duplicate && onDuplicate === 'update'
        ? { ...entry, id: duplicate.id, savedAt: duplicate.savedAt }
        : entry
      const stored = await withStore('readwrite', async store => {
        await requestToPromise(store.put(finalEntry))
        return finalEntry
      })
      if (!stored) memory = [finalEntry, ...memory.filter(item => item.id !== finalEntry.id)]
      return { entry: finalEntry, duplicate: duplicate || null, updated: Boolean(duplicate) && onDuplicate === 'update' }
    },

    async remove(id) {
      const key = String(id)
      const touched = await withStore('readwrite', async store => {
        await requestToPromise(store.delete(key))
        return true
      })
      if (!touched) memory = memory.filter(item => item.id !== key)

      await this.removeAssetEvidenceLinks({ evidenceId: key })
      return true
    },


    async removeByProject(project) {
      const doomed = (await readProject(project)).map(item => item.id)
      const touched = await withStore('readwrite', async store => {
        for (const id of doomed) await requestToPromise(store.delete(String(id)))
        return true
      })
      if (!touched) memory = memory.filter(item => !doomed.includes(item.id))
      for (const id of doomed) await this.removeAssetEvidenceLinks({ evidenceId: id })
      return doomed.length
    },

    async clear() {
      const touched = await withStore('readwrite', async store => {
        await requestToPromise(store.clear())
        return true
      })
      if (!touched) memory = []
      await this.removeAssetEvidenceLinks({})
      return true
    },




    async linkAssetEvidence({ assetId, evidenceId, project = '', createdAt = Date.now() } = {}) {
      const link = normalizeAssetEvidenceLink({ assetId, evidenceId, project, createdAt })
      const existing = await this.listAssetEvidenceLinks({ assetId: link.assetId, evidenceId: link.evidenceId })
      if (existing.length) return { link: existing[0], created: false }
      const all = await this.listAssetEvidenceLinks()
      if (all.length >= MAX_LINKS) {
        const error = new Error(`关联关系已达上限（${MAX_LINKS} 条）；请先清理不再需要的关联。`)
        error.code = 'LINK_LIMIT'
        throw error
      }
      const touched = await withStore('readwrite', async store => {
        await requestToPromise(store.put(link))
        return true
      }, LINKS_STORE)
      if (!touched) memoryLinks = [link, ...memoryLinks.filter(row => row.id !== link.id)]
      return { link, created: true }
    },


    async listAssetEvidenceLinks({ assetId, evidenceId, project } = {}) {
      const rows = await withStore('readonly', store => requestToPromise(store.getAll()), LINKS_STORE)
      const list = Array.isArray(rows) ? rows : memoryLinks
      return list
        .filter(row => (assetId === undefined || String(row.assetId) === String(assetId))
          && (evidenceId === undefined || String(row.evidenceId) === String(evidenceId))
          && (project === undefined || String(row.project || '') === String(project)))
        .sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0))
    },

    async removeAssetEvidenceLink(id) {
      const key = String(id)
      const touched = await withStore('readwrite', async store => {
        await requestToPromise(store.delete(key))
        return true
      }, LINKS_STORE)
      if (!touched) memoryLinks = memoryLinks.filter(row => row.id !== key)
      return true
    },


    async removeAssetEvidenceLinks({ assetId, evidenceId } = {}) {
      const doomed = (await this.listAssetEvidenceLinks({ assetId, evidenceId })).map(row => row.id)
      if (!doomed.length) return 0
      const touched = await withStore('readwrite', async store => {
        for (const id of doomed) await requestToPromise(store.delete(id))
        return true
      }, LINKS_STORE)
      if (!touched) memoryLinks = memoryLinks.filter(row => !doomed.includes(row.id))
      return doomed.length
    },


    async importMany(entries) {
      const rows = Array.isArray(entries) ? entries : []
      if (!rows.length) return 0
      const touched = await withStore('readwrite', async store => {
        for (const row of rows) await requestToPromise(store.put(row))
        return true
      })
      if (!touched) memory = [...rows, ...memory.filter(item => !rows.some(row => row.id === item.id))]
      return rows.length
    },



    async remapProjects(mappings, { dryRun = false, now = Date.now(), expectedSnapshot = null, claimProjections = [] } = {}) {
      const map = new Map(mappings.map(item => [item.from, item.to]))
      const evidenceBefore = (await readAll()).filter(item => map.has(item.project))
      const linksBefore = (await this.listAssetEvidenceLinks()).filter(item => map.has(item.project))
      const claimsBefore = (await this.listResearchClaims()).filter(item => map.has(item.project))
      const ledgerBefore = (await this.listResearchLedger()).filter(item => map.has(item.project))
      const evidenceAfter = evidenceBefore.map(item => ({
        ...item, project: map.get(item.project), workspaceId: workspaceIdForProject(map.get(item.project)),
        legacyProject: item.legacyProject || item.project, updatedAt: now,
      }))
      const linksAfter = linksBefore.map(item => ({ ...item, project: map.get(item.project), legacyProject: item.legacyProject || item.project }))
      const movedClaims = new Map(claimProjections.map(item => [item.id, item]))
      const claimsAfter = claimsBefore.map(item => movedClaims.get(item.id) || ({ ...item, project: map.get(item.project), workspaceId: workspaceIdForProject(map.get(item.project)), legacyProject: item.legacyProject || item.project }))
      const ledgerAfter = ledgerBefore.map(item => ({ ...item, project: map.get(item.project), workspaceId: workspaceIdForProject(map.get(item.project)), legacyProject: item.legacyProject || item.project }))
      const all = await readAll()
      const proposed = [...all.filter(item => !map.has(item.project)), ...evidenceAfter]
      for (const item of evidenceAfter) {
        const other = findDuplicate(proposed.filter(row => row.id !== item.id), item)
        if (other) throw new Error(`「${item.title}」迁移到「${item.project}」时与现有来源重复。`)
      }
      const snapshot = { evidenceBefore, evidenceAfter, linksBefore, linksAfter, claimsBefore, claimsAfter, ledgerBefore, ledgerAfter }
      if (expectedSnapshot && (JSON.stringify(expectedSnapshot.evidenceBefore) !== JSON.stringify(evidenceBefore)
        || JSON.stringify(expectedSnapshot.linksBefore) !== JSON.stringify(linksBefore)
        || JSON.stringify(expectedSnapshot.claimsBefore) !== JSON.stringify(claimsBefore)
        || JSON.stringify(expectedSnapshot.ledgerBefore || []) !== JSON.stringify(ledgerBefore))) {
        throw new Error('项目整理预览后证据已变化，未写入；请重新预览。')
      }
      if (dryRun) return snapshot
      const db = await connect()
      if (db) {
        await withTransaction(db, [STORE, LINKS_STORE, CLAIMS_STORE, LEDGER_STORE], 'readwrite', tx => {
          for (const row of evidenceAfter) tx.objectStore(STORE).put(row)
          for (const row of linksAfter) tx.objectStore(LINKS_STORE).put(row)
          for (const row of claimsAfter) tx.objectStore(CLAIMS_STORE).put(row)
          for (const row of ledgerAfter) tx.objectStore(LEDGER_STORE).put(row)
        }, { errorMessage: '证据项目迁移失败', abortMessage: '证据项目迁移中止' })
      } else {
        memory = [...evidenceAfter, ...memory.filter(item => !map.has(item.project))]
        memoryLinks = [...linksAfter, ...memoryLinks.filter(item => !map.has(item.project))]
        memoryResearchClaims = [...claimsAfter, ...memoryResearchClaims.filter(item => !map.has(item.project))]
        memoryResearchLedger = [...ledgerAfter, ...memoryResearchLedger.filter(item => !map.has(item.project))]
      }
      return snapshot
    },

    async restoreProjectOrganization(snapshot, { validateOnly = false } = {}) {
      const current = await readAll()
      const currentLinks = await this.listAssetEvidenceLinks()
      const currentClaims = await this.listResearchClaims()
      const currentLedger = await this.listResearchLedger()
      for (const row of snapshot.evidenceAfter || []) {
        const value = JSON.stringify(current.find(item => item.id === row.id))
        const before = JSON.stringify(snapshot.evidenceBefore.find(item => item.id === row.id))
        if (value !== JSON.stringify(row) && value !== before) throw new Error('证据在整理后已变化，不能自动撤销。')
      }
      for (const row of snapshot.linksAfter || []) {
        const value = JSON.stringify(currentLinks.find(item => item.id === row.id))
        const before = JSON.stringify(snapshot.linksBefore.find(item => item.id === row.id))
        if (value !== JSON.stringify(row) && value !== before) throw new Error('关联在整理后已变化，不能自动撤销。')
      }
      for (const row of snapshot.claimsAfter || []) {
        const value = JSON.stringify(currentClaims.find(item => item.id === row.id))
        const before = JSON.stringify(snapshot.claimsBefore.find(item => item.id === row.id))
        if (value !== JSON.stringify(row) && value !== before) throw new Error('研究论断在整理后已变化，不能自动撤销。')
      }
      for (const row of snapshot.ledgerAfter || []) {
        const value = JSON.stringify(currentLedger.find(item => item.id === row.id))
        const before = JSON.stringify((snapshot.ledgerBefore || []).find(item => item.id === row.id))
        if (value !== JSON.stringify(row) && value !== before) throw new Error('科研账本在整理后已变化，不能自动撤销。')
      }
      if (validateOnly) return true
      const db = await connect()
      if (db) {
        const tx = db.transaction([STORE, LINKS_STORE, CLAIMS_STORE, LEDGER_STORE], 'readwrite')
        for (const row of snapshot.evidenceBefore || []) tx.objectStore(STORE).put(row)
        for (const row of snapshot.linksBefore || []) tx.objectStore(LINKS_STORE).put(row)
        for (const row of snapshot.claimsBefore || []) tx.objectStore(CLAIMS_STORE).put(row)
        for (const row of snapshot.ledgerBefore || []) tx.objectStore(LEDGER_STORE).put(row)
        await new Promise((resolve, reject) => {
          tx.oncomplete = resolve
          tx.onerror = () => reject(tx.error || new Error('证据项目撤销失败'))
          tx.onabort = () => reject(tx.error || new Error('证据项目撤销中止'))
        })
      } else {
        const beforeIds = new Set((snapshot.evidenceBefore || []).map(item => item.id))
        const linkIds = new Set((snapshot.linksBefore || []).map(item => item.id))
        memory = [...snapshot.evidenceBefore, ...memory.filter(item => !beforeIds.has(item.id))]
        memoryLinks = [...snapshot.linksBefore, ...memoryLinks.filter(item => !linkIds.has(item.id))]
        const claimIds = new Set((snapshot.claimsBefore || []).map(item => item.id))
        memoryResearchClaims = [...snapshot.claimsBefore, ...memoryResearchClaims.filter(item => !claimIds.has(item.id))]
        const ledgerIds = new Set((snapshot.ledgerBefore || []).map(item => item.id))
        memoryResearchLedger = [...(snapshot.ledgerBefore || []), ...memoryResearchLedger.filter(item => !ledgerIds.has(item.id))]
      }
      return true
    },
  }
}



const UNIFIED_CLAIM_API = '/dsh-research-kit/claim-review'
const unifiedClaimInFlight = new Map()

async function requestResearchClaims(project, body, signal) {
  const response = await fetch(body ? UNIFIED_CLAIM_API : `${UNIFIED_CLAIM_API}?project=${encodeURIComponent(project)}`, {
    method: body ? 'POST' : 'GET', headers: body ? { 'Content-Type': 'application/json' } : undefined,
    body: body ? JSON.stringify({ ...body, project }) : undefined,
    signal: signal || AbortSignal.timeout(10000),
  })
  const result = await response.json()
  if (!response.ok || !result.ok) throw new Error(result.error || `HTTP ${response.status}`)
  return result
}

function projectClaimProjection(claim, project) {
  const ids = claim.evidence_ids || []
  const links = (claim.links || []).filter(link => ids.includes(link.evidenceId))
  const resolvedProject = claim.workspace_id === 'workspace:unassigned' ? '' : claim.project || project
  return { ...claim, project: resolvedProject, workspaceId: workspaceIdForProject(resolvedProject),
    links: [...links, ...ids.filter(id => !links.some(link => link.evidenceId === id)).map(evidenceId => ({ evidenceId, stance: 'unassessed' }))],
    createdAt: Date.parse(claim.created_at) || 0, updatedAt: Date.parse(claim.updated_at) || 0,
    reviewSource: 'file-ledger' }
}

function synchronizeResearchClaims(store, project = '') {
  const key = String(project || 'default')
  if (unifiedClaimInFlight.has(key)) return unifiedClaimInFlight.get(key)
  const task = (async () => {
    const local = (await store.listResearchClaims()).filter(row => (row.project || 'default') === key)
    const pending = local.filter(claim => claim.reviewSource !== 'file-ledger')
    for (let at = 0; at < pending.length; at += 10) {
      await requestResearchClaims(key || 'default', { action: 'import_local', claims: pending.slice(at, at + 10) })
    }
    let offset = 0; const rows = []; let first
    do {
      const response = await fetch(`${UNIFIED_CLAIM_API}?project=${encodeURIComponent(key || 'default')}&offset=${offset}`, { signal: AbortSignal.timeout(10000) })
      const result = await response.json()
      if (!response.ok || !result.ok || !Array.isArray(result.claims)) throw new Error(result.error || '读取 Claim 台账失败。')
      first ||= result
      rows.push(...result.claims.map(claim => projectClaimProjection(claim, key)))
      if (result.next_offset == null) break
      if (!Number.isInteger(result.next_offset) || result.next_offset <= offset) throw new Error('Claim 分页响应无效。')
      offset = result.next_offset
    } while (true)
    await store.cacheResearchClaims(rows)
    return { claims: rows, evidence: first.evidence || [], evidence_limit_reached: first.evidence_limit_reached }
  })().finally(() => unifiedClaimInFlight.delete(key))
  unifiedClaimInFlight.set(key, task)
  return task
}

async function synchronizeClaimScopes(store, project) {
  const projects = typeof project === 'string' ? [project || 'default'] : [...new Set(['default',
    ...(await store.listProjects()),
    ...(await store.listResearchClaims()).map(row => row.project || 'default'),
  ])]
  if (typeof project !== 'string') {
    const response = await fetch(`${UNIFIED_CLAIM_API}?projects=1`, { signal: AbortSignal.timeout(10000) })
    const result = await response.json()
    if (!response.ok || !result.ok) throw new Error(result.error || '无法读取 Claim 课题列表。')
    for (const name of result.projects || []) if (!projects.includes(name)) projects.push(name)
  }
  const results = []
  for (const scope of projects) results.push(...(await synchronizeResearchClaims(store, scope)).claims)
  return results
}


















const KNOWLEDGE_DB_NAME = 'dsh-research-kit-knowledge'
const KNOWLEDGE_DB_VERSION = 1
const KNOWLEDGE_NODE_STORE = 'nodes'
const KNOWLEDGE_CLAIM_STORE = 'claims'
const KNOWLEDGE_NODE_ID_PREFIX = 'kn-'
const KNOWLEDGE_CLAIM_ID_PREFIX = 'kc-'


const MAX_SOURCES_PER_RECORD = 5
const MAX_SOURCE_EXCERPT_CHARS = 200
const MAX_EVIDENCE_LINKS_PER_NODE = 12

function clampKnowledgeText(value, max) {
  const text = String(value || '').trim()
  return text.length > max ? text.slice(0, max) : text
}

function knowledgeSourceId(source) {
  return `${source.sessionId || ''}:${Number.isFinite(source.seq) ? source.seq : ''}`
}

function normalizeKnowledgeSource(input = {}) {
  const excerpt = String(input.excerpt || '').trim()
  return {
    sessionId: String(input.sessionId || ''),
    seq: Number.isFinite(Number(input.seq)) ? Number(input.seq) : null,
    turn: Number.isFinite(Number(input.turn)) ? Number(input.turn) : null,
    at: Number(input.at) || 0,
    excerpt: excerpt.length > MAX_SOURCE_EXCERPT_CHARS ? `${excerpt.slice(0, MAX_SOURCE_EXCERPT_CHARS - 1)}…` : excerpt,
  }
}


function mergeKnowledgeSources(existing = [], incoming = []) {
  const rows = Array.isArray(existing) ? [...existing] : []
  const seen = new Set(rows.map(knowledgeSourceId))
  for (const raw of Array.isArray(incoming) ? incoming : []) {
    const source = normalizeKnowledgeSource(raw)
    if (source.excerpt === '' && !source.sessionId && source.seq === null) continue
    const id = knowledgeSourceId(source)
    if (seen.has(id)) continue
    seen.add(id)
    rows.push(source)
  }
  return rows.slice(0, MAX_SOURCES_PER_RECORD)
}

function knowledgeNodeIdFor(key) {
  return `${KNOWLEDGE_NODE_ID_PREFIX}${hashKey(key)}`
}



function knowledgeClaimKeyFor({ fromKey, relation, toKey, polarity }) {
  return `${fromKey}|${relation}|${toKey}|${polarity}`
}

function knowledgeClaimIdFor(identity) {
  return `${KNOWLEDGE_CLAIM_ID_PREFIX}${hashKey(identity)}`
}




function knowledgeRows(value) {
  return (Array.isArray(value) ? value : []).filter(row => row && typeof row === 'object')
}

function sortKnowledgeNodes(rows) {
  return knowledgeRows(rows).sort((a, b) => ((a.key ?? '') < (b.key ?? '') ? -1 : (a.key ?? '') > (b.key ?? '') ? 1 : 0))
}

function sortKnowledgeClaims(rows) {
  return knowledgeRows(rows).sort((a, b) => ((a.id ?? '') < (b.id ?? '') ? -1 : (a.id ?? '') > (b.id ?? '') ? 1 : 0))
}





const KNOWLEDGE_BACKUP_KIND = 'dsh-research-kit-knowledge'
const KNOWLEDGE_BACKUP_VERSION = 1

function serializeKnowledgeBackup({ nodes = [], claims = [] } = {}) {
  return JSON.stringify({
    kind: KNOWLEDGE_BACKUP_KIND,
    version: KNOWLEDGE_BACKUP_VERSION,
    exportedAt: Date.now(),
    nodes: Array.isArray(nodes) ? nodes : [],
    claims: Array.isArray(claims) ? claims : [],
  }, null, 2)
}


function parseKnowledgeBackup(text) {
  const raw = String(text || '').trim()
  if (!raw) throw new Error('备份内容为空。')
  let parsed
  try { parsed = JSON.parse(raw) } catch { throw new Error('备份不是合法 JSON，请确认复制完整。') }
  if (parsed?.kind !== KNOWLEDGE_BACKUP_KIND) throw new Error('这不是自动沉淀知识库的备份文件。')
  if (Number(parsed?.version) > KNOWLEDGE_BACKUP_VERSION) throw new Error(`备份版本 ${parsed.version} 高于当前支持的 ${KNOWLEDGE_BACKUP_VERSION}，请升级 Research Kit 后再恢复。`)
  if (!Array.isArray(parsed.nodes) || !Array.isArray(parsed.claims)) throw new Error('备份文件缺少 nodes/claims 字段。')
  return { nodes: parsed.nodes, claims: parsed.claims }
}



function mergeKnowledgeBackup(existingNodes = [], existingClaims = [], incomingNodes = [], incomingClaims = [], now = Date.now()) {
  const knownNodes = new Map(Array.isArray(existingNodes) ? existingNodes.map(row => [row.key, row]) : [])
  const outNodes = []
  let addedNodes = 0
  let skippedNodes = 0
  let invalidNodes = 0
  for (const raw of Array.isArray(incomingNodes) ? incomingNodes : []) {
    if (!raw || typeof raw !== 'object') { invalidNodes++; continue }
    const kind = KNOWLEDGE_KINDS.includes(raw.kind) ? raw.kind : ''
    const label = clampKnowledgeText(raw.label, 60)
    if (!kind || !label) { invalidNodes++; continue }
    const key = clampKnowledgeText(raw.key, 200) || knowledgeKeyFor(kind, kind === 'entity' ? raw.entityKind : '', label)
    if (knownNodes.has(key)) { skippedNodes++; continue }
    const row = {
      id: knowledgeNodeIdFor(key),
      key,
      kind,
      entityKind: kind === 'entity' ? (KNOWLEDGE_ENTITY_KINDS.includes(raw.entityKind) ? raw.entityKind : 'generic') : '',
      label,
      status: KNOWLEDGE_STATUSES.includes(raw.status) ? raw.status : 'to_verify',
      project: clampKnowledgeText(raw.project, 120),
      sources: mergeKnowledgeSources([], raw.sources),
      evidenceIds: (Array.isArray(raw.evidenceIds) ? raw.evidenceIds.map(String).filter(Boolean) : []).slice(0, MAX_EVIDENCE_LINKS_PER_NODE),
      assetId: clampKnowledgeText(raw.assetId, 120),
      createdAt: Number(raw.createdAt) || now,
      updatedAt: Number(raw.updatedAt) || now,
    }
    knownNodes.set(key, row)
    outNodes.push(row)
    addedNodes++
  }

  const keyOfNodeId = new Map()
  for (const row of knownNodes.values()) keyOfNodeId.set(row.id, row.key)
  const knownClaims = new Map(Array.isArray(existingClaims) ? existingClaims.map(row => [row.id, row]) : [])
  const outClaims = []
  let addedClaims = 0
  let skippedClaims = 0
  let invalidClaims = 0
  for (const raw of Array.isArray(incomingClaims) ? incomingClaims : []) {
    if (!raw || typeof raw !== 'object') { invalidClaims++; continue }
    const relation = clampKnowledgeText(raw.relation, 40)
    const polarity = ['positive', 'negative', 'uncertain', 'neutral'].includes(raw.polarity) ? raw.polarity : 'neutral'
    const fromKey = keyOfNodeId.get(String(raw.from || ''))
    const toKey = keyOfNodeId.get(String(raw.to || ''))
    if (!relation || !fromKey || !toKey) { invalidClaims++; continue }
    const identity = knowledgeClaimKeyFor({ fromKey, relation, toKey, polarity })
    const id = knowledgeClaimIdFor(identity)
    if (knownClaims.has(id)) { skippedClaims++; continue }
    const row = {
      id,
      key: identity,
      from: knowledgeNodeIdFor(fromKey),
      to: knowledgeNodeIdFor(toKey),
      relation,
      polarity,
      status: KNOWLEDGE_STATUSES.includes(raw.status) ? raw.status : 'to_verify',
      project: clampKnowledgeText(raw.project, 120),
      sources: mergeKnowledgeSources([], raw.sources),
      createdAt: Number(raw.createdAt) || now,
      updatedAt: Number(raw.updatedAt) || now,
    }
    knownClaims.set(id, row)
    outClaims.push(row)
    addedClaims++
  }
  return { nodes: outNodes, claims: outClaims, addedNodes, skippedNodes, invalidNodes, addedClaims, skippedClaims, invalidClaims }
}

function createKnowledgeStore() {
  let dbPromise = null
  let degraded = false
  const memory = { nodes: [], claims: [] }

  const connect = () => {
    if (degraded) return Promise.resolve(null)
    if (dbPromise) return dbPromise
    const factory = indexedDbFactory()
    if (!factory) { degraded = true; return Promise.resolve(null) }
    dbPromise = new Promise(resolve => {
      let request
      try { request = factory.open(KNOWLEDGE_DB_NAME, KNOWLEDGE_DB_VERSION) } catch { degraded = true; resolve(null); return }
      request.onupgradeneeded = () => {
        const db = request.result
        if (!db.objectStoreNames.contains(KNOWLEDGE_NODE_STORE)) {
          const nodes = db.createObjectStore(KNOWLEDGE_NODE_STORE, { keyPath: 'id' })
          nodes.createIndex('key', 'key')
          nodes.createIndex('kind', 'kind')
          nodes.createIndex('updatedAt', 'updatedAt')
        }
        if (!db.objectStoreNames.contains(KNOWLEDGE_CLAIM_STORE)) {
          const claims = db.createObjectStore(KNOWLEDGE_CLAIM_STORE, { keyPath: 'id' })
          claims.createIndex('from', 'from')
          claims.createIndex('to', 'to')
          claims.createIndex('updatedAt', 'updatedAt')
        }
      }
      request.onsuccess = () => { if (!request.result) degraded = true; resolve(request.result || null) }
      request.onerror = () => { degraded = true; resolve(null) }
      request.onblocked = () => { degraded = true; resolve(null) }
    })
    return dbPromise
  }

  const withStore = async (storeName, mode, run) => {
    const db = await connect()
    if (!db) return undefined
    return withObjectStore(db, storeName, mode, run)
  }

  const readNodes = async () => {
    const rows = await withStore(KNOWLEDGE_NODE_STORE, 'readonly', store => requestToPromise(store.getAll()))
    return sortKnowledgeNodes(Array.isArray(rows) ? rows : memory.nodes)
  }

  const readClaims = async () => {
    const rows = await withStore(KNOWLEDGE_CLAIM_STORE, 'readonly', store => requestToPromise(store.getAll()))
    return sortKnowledgeClaims(Array.isArray(rows) ? rows : memory.claims)
  }

  const putRows = async (storeName, rows) => {
    if (!rows.length) return true
    const touched = await withStore(storeName, 'readwrite', async store => {
      for (const row of rows) await requestToPromise(store.put(row))
      return true
    })
    if (!touched) {
      const bucket = storeName === KNOWLEDGE_NODE_STORE ? 'nodes' : 'claims'
      const merged = [...rows, ...memory[bucket].filter(item => !rows.some(row => row.id === item.id))]
      memory[bucket] = bucket === 'nodes' ? sortKnowledgeNodes(merged) : sortKnowledgeClaims(merged)
    }
    return true
  }

  const deleteRow = async (storeName, id) => {
    const touched = await withStore(storeName, 'readwrite', store => requestToPromise(store.delete(id)))
    if (!touched) {
      const bucket = storeName === KNOWLEDGE_NODE_STORE ? 'nodes' : 'claims'
      memory[bucket] = memory[bucket].filter(item => item.id !== id)
    }
    return true
  }

  return {

    isDegraded: () => degraded || indexedDbFactory() === null,

    async listNodes({ kind } = {}) {
      const rows = await readNodes()
      return kind ? rows.filter(row => row.kind === kind) : rows
    },

    async listClaims() {
      return readClaims()
    },

    async remapProjects(mappings, { dryRun = false, expectedSnapshot = null } = {}) {
      const map = new Map(mappings.map(item => [item.from, item.to]))
      const nodesBefore = (await readNodes()).filter(item => map.has(item.project))
      const claimsBefore = (await readClaims()).filter(item => map.has(item.project))
      const nodesAfter = nodesBefore.map(item => ({ ...item, project: map.get(item.project), legacyProject: item.legacyProject || item.project }))
      const claimsAfter = claimsBefore.map(item => ({ ...item, project: map.get(item.project), legacyProject: item.legacyProject || item.project }))
      const snapshot = { nodesBefore, nodesAfter, claimsBefore, claimsAfter }
      if (expectedSnapshot && (JSON.stringify(expectedSnapshot.nodesBefore) !== JSON.stringify(nodesBefore)
        || JSON.stringify(expectedSnapshot.claimsBefore) !== JSON.stringify(claimsBefore))) {
        throw new Error('项目整理预览后知识库已变化，未写入；请重新预览。')
      }
      if (dryRun) return snapshot
      const db = await connect()
      if (db) {
        await withTransaction(db, [KNOWLEDGE_NODE_STORE, KNOWLEDGE_CLAIM_STORE], 'readwrite', tx => {
          for (const row of nodesAfter) tx.objectStore(KNOWLEDGE_NODE_STORE).put(row)
          for (const row of claimsAfter) tx.objectStore(KNOWLEDGE_CLAIM_STORE).put(row)
        }, { errorMessage: '知识项目迁移失败', abortMessage: '知识项目迁移中止' })
      } else {
        memory.nodes = [...nodesAfter, ...memory.nodes.filter(item => !map.has(item.project))]
        memory.claims = [...claimsAfter, ...memory.claims.filter(item => !map.has(item.project))]
      }
      return snapshot
    },

    async restoreProjectOrganization(snapshot, { validateOnly = false } = {}) {
      const nodes = await readNodes(), claims = await readClaims()
      for (const row of snapshot.nodesAfter || []) {
        const value = JSON.stringify(nodes.find(item => item.id === row.id))
        const before = JSON.stringify(snapshot.nodesBefore.find(item => item.id === row.id))
        if (value !== JSON.stringify(row) && value !== before) throw new Error('知识节点在整理后已变化，不能自动撤销。')
      }
      for (const row of snapshot.claimsAfter || []) {
        const value = JSON.stringify(claims.find(item => item.id === row.id))
        const before = JSON.stringify(snapshot.claimsBefore.find(item => item.id === row.id))
        if (value !== JSON.stringify(row) && value !== before) throw new Error('知识关系在整理后已变化，不能自动撤销。')
      }
      if (validateOnly) return true
      await putRows(KNOWLEDGE_NODE_STORE, snapshot.nodesBefore || [])
      await putRows(KNOWLEDGE_CLAIM_STORE, snapshot.claimsBefore || [])
      return true
    },




    async applyExtraction({ nodes = [], claims = [], source = {}, project = '', now = Date.now() } = {}) {
      const projectKey = clampKnowledgeText(project, 120)
      const origin = normalizeKnowledgeSource(source)
      const hasOrigin = Boolean(origin.excerpt || origin.sessionId || origin.seq !== null)
      const existingNodes = await readNodes()
      const existingClaims = await readClaims()
      const nodeById = new Map(existingNodes.map(row => [row.id, row]))
      const nodeIdByKey = new Map(existingNodes.map(row => [row.key, row.id]))
      const claimById = new Map(existingClaims.map(row => [row.id, row]))
      const touchedNodes = []
      const touchedClaims = []
      let addedNodes = 0
      let mergedNodes = 0
      let addedClaims = 0
      let mergedClaims = 0
      let skippedNodes = 0
      let skippedClaims = 0

      for (const draft of Array.isArray(nodes) ? nodes : []) {
        let clean
        try { clean = normalizeKnowledgeNodeDraft(draft) } catch { skippedNodes++; continue }
        const id = knowledgeNodeIdFor(clean.key)
        const previous = nodeById.get(id)
        const incoming = hasOrigin ? [{ ...origin, excerpt: draft.excerpt || origin.excerpt }] : []
        if (previous) {
          const next = {
            ...previous,
            label: clean.label,
            entityKind: clean.kind === 'entity' ? (clean.entityKind || previous.entityKind) : previous.entityKind,
            project: previous.project || projectKey,
            sources: mergeKnowledgeSources(previous.sources, incoming),

            status: previous.status === 'to_verify' ? 'to_verify' : previous.status,
            updatedAt: now,
          }
          nodeById.set(id, next)
          touchedNodes.push(next)
          mergedNodes++
        } else {
          const row = {
            id,
            key: clean.key,
            kind: clean.kind,
            entityKind: clean.entityKind,
            label: clean.label,
            status: 'to_verify',
            project: projectKey,
            sources: mergeKnowledgeSources([], incoming),
            evidenceIds: [],
            assetId: '',
            createdAt: now,
            updatedAt: now,
          }
          nodeById.set(id, row)
          nodeIdByKey.set(clean.key, id)
          touchedNodes.push(row)
          addedNodes++
        }
      }


      for (const draft of Array.isArray(claims) ? claims : []) {
        let clean
        try { clean = normalizeKnowledgeClaimDraft(draft) } catch { skippedClaims++; continue }
        const fromId = nodeIdByKey.get(clean.fromKey)
        const toId = nodeIdByKey.get(clean.toKey)
        if (!fromId || !toId) { skippedClaims++; continue }
        const identity = knowledgeClaimKeyFor(clean)
        const id = knowledgeClaimIdFor(identity)
        const previous = claimById.get(id)
        const incoming = hasOrigin ? [{ ...origin, excerpt: draft.excerpt || origin.excerpt }] : []
        const row = {
          id,
          key: identity,
          from: fromId,
          to: toId,
          relation: clean.relation,
          polarity: clean.polarity,
          status: previous && previous.status !== 'to_verify' ? previous.status : 'to_verify',
          project: (previous && previous.project) || projectKey,
          sources: mergeKnowledgeSources(previous?.sources, incoming),
          createdAt: previous?.createdAt || now,
          updatedAt: now,
        }
        claimById.set(id, row)
        touchedClaims.push(row)
        if (previous) mergedClaims++
        else addedClaims++
      }

      await putRows(KNOWLEDGE_NODE_STORE, touchedNodes)
      await putRows(KNOWLEDGE_CLAIM_STORE, touchedClaims)
      return {
        nodes: await readNodes(),
        claims: await readClaims(),
        addedNodes, mergedNodes, skippedNodes,
        addedClaims, mergedClaims, skippedClaims,
      }
    },

    async setNodeStatus(id, status) {
      if (!KNOWLEDGE_STATUSES.includes(status)) throw new Error(`未知的核验状态：${status}`)
      const rows = await readNodes()
      const row = rows.find(item => item.id === id)
      if (!row || row.status === status) return row || null
      const next = { ...row, status, updatedAt: Date.now() }
      await putRows(KNOWLEDGE_NODE_STORE, [next])
      return next
    },

    async setClaimStatus(id, status) {
      if (!KNOWLEDGE_STATUSES.includes(status)) throw new Error(`未知的核验状态：${status}`)
      const rows = await readClaims()
      const row = rows.find(item => item.id === id)
      if (!row || row.status === status) return row || null
      const next = { ...row, status, updatedAt: Date.now() }
      await putRows(KNOWLEDGE_CLAIM_STORE, [next])
      return next
    },

    async linkEvidence(nodeId, evidenceId) {
      const clean = String(evidenceId || '')
      if (!clean) return null
      const rows = await readNodes()
      const row = rows.find(item => item.id === nodeId)
      if (!row) return null
      if ((row.evidenceIds || []).includes(clean)) return row
      const next = { ...row, evidenceIds: [...(row.evidenceIds || []), clean].slice(0, MAX_EVIDENCE_LINKS_PER_NODE), updatedAt: Date.now() }
      await putRows(KNOWLEDGE_NODE_STORE, [next])
      return next
    },

    async setAssetId(nodeId, assetId) {
      const clean = String(assetId || '')
      if (!clean) return null
      const rows = await readNodes()
      const row = rows.find(item => item.id === nodeId)
      if (!row) return null
      if (row.assetId === clean) return row
      const next = { ...row, assetId: clean, updatedAt: Date.now() }
      await putRows(KNOWLEDGE_NODE_STORE, [next])
      return next
    },


    async importBackup({ nodes = [], claims = [], now = Date.now() } = {}) {
      const merged = mergeKnowledgeBackup(await readNodes(), await readClaims(), nodes, claims, now)
      await putRows(KNOWLEDGE_NODE_STORE, merged.nodes)
      await putRows(KNOWLEDGE_CLAIM_STORE, merged.claims)
      return { ...merged, nodes: await readNodes(), claims: await readClaims() }
    },



    async removeNode(nodeId) {
      const claims = await readClaims()
      const doomed = claims.filter(row => row.from === nodeId || row.to === nodeId)
      for (const row of doomed) await deleteRow(KNOWLEDGE_CLAIM_STORE, row.id)
      await deleteRow(KNOWLEDGE_NODE_STORE, nodeId)
      return true
    },


    async clear() {
      const clearedNodes = await withStore(KNOWLEDGE_NODE_STORE, 'readwrite', store => requestToPromise(store.clear()))
      const clearedClaims = await withStore(KNOWLEDGE_CLAIM_STORE, 'readwrite', store => requestToPromise(store.clear()))
      if (clearedNodes === undefined && clearedClaims === undefined) { memory.nodes = []; memory.claims = [] }
      return true
    },
  }
}




