const AUTO_DEPOSIT_STORAGE_KEY = 'dsh-research-kit.auto-deposit.enabled'
const AUTO_DEPOSIT_EVENT = 'dsh-research-kit:auto-deposit-changed'
const DEPOSITION_TAG = '自动沉淀'

const DEPOSITION_SOURCE_DATABASE = '会话回答'



const MIN_DEPOSITION_MESSAGE_CHARS = 12

const DEPOSIT_ASSET_KINDS = ['question', 'hypothesis', 'finding', 'method']
const DEPOSIT_ASSET_THINKING_KIND = { question: 'question', hypothesis: 'assumption', finding: 'conclusion', method: 'method' }



function isAutoDepositEnabled() {
  try { return globalThis.localStorage?.getItem(AUTO_DEPOSIT_STORAGE_KEY) === '1' } catch { return false }
}

function setAutoDepositEnabled(value) {
  try { globalThis.localStorage?.setItem(AUTO_DEPOSIT_STORAGE_KEY, value ? '1' : '0') } catch { /* 不可用时仅本次会话生效 */ }
  try {
    if (typeof window !== 'undefined' && typeof window.dispatchEvent === 'function') {
      window.dispatchEvent(new CustomEvent(AUTO_DEPOSIT_EVENT, { detail: { enabled: Boolean(value) } }))
    }
  } catch { /* 通知失败不影响开关本身 */ }
  return Boolean(value)
}

function onAutoDepositChange(listener) {
  if (typeof window === 'undefined' || typeof window.addEventListener !== 'function') return () => {}
  const handler = () => { try { listener(isAutoDepositEnabled()) } catch { /* 单个监听失败不影响其余 */ } }
  window.addEventListener(AUTO_DEPOSIT_EVENT, handler)
  return () => window.removeEventListener(AUTO_DEPOSIT_EVENT, handler)
}





function depositionCursorKey(sessionId) {
  return `dsh-research-kit.deposition.cursor.${String(sessionId || 'local')}`
}

function readDepositionCursor(sessionId) {
  try { return Number(globalThis.localStorage?.getItem(depositionCursorKey(sessionId))) || 0 } catch { return 0 }
}

function writeDepositionCursor(sessionId, seq) {
  try { globalThis.localStorage?.setItem(depositionCursorKey(sessionId), String(Number(seq) || 0)) } catch { /* 不可用时重启后会重复提取一次，可接受 */ }
}



function normalizeTitleForDedupe(title) {
  return normalizeKnowledgeLabel(title).toLowerCase()
}

const EMPTY_SUMMARY = { extracted: false, addedNodes: 0, mergedNodes: 0, addedClaims: 0, mergedClaims: 0, citations: 0, savedEvidence: 0, duplicateEvidence: 0, failedEvidence: 0, savedAssets: 0, skippedAssets: 0 }



let latestDepositionSummary = null

function lastDepositionSummary() {
  return latestDepositionSummary
}



function assetDedupeKey(title, project) {
  return `${normalizeTitleForDedupe(title)}::${String(project || '').trim()}`
}




async function depositAssistantMessage({
  text,
  selection,
  traceAnswerSources = false,
  sessionId = '',
  seq = null,
  turn = null,
  at = 0,
  assetProvider = null,
  store = knowledgeStore(),
  saveEvidence = saveEvidenceEntry,
  activeProject,
  now = Date.now(),
} = {}) {
  const summary = { ...EMPTY_SUMMARY, sessionId: String(sessionId || ''), seq: Number.isFinite(Number(seq)) ? Number(seq) : null }
  const source = String(text || '')
  if (!source.trim()) return summary
  const project = activeProject !== undefined ? activeProject : getActiveProject()
  const extracted = traceAnswerSources ? extractAnswerEvidence(source, project) : extractKnowledge(source)
  const selectedKeys = Array.isArray(selection?.nodeKeys) ? new Set(selection.nodeKeys) : null
  const selectedCitations = Array.isArray(selection?.citationIndexes) ? new Set(selection.citationIndexes) : null
  const referencesByNode = new Map((extracted.rows || []).map(row => [row.nodeKey,
    row.references.filter(ref => !selectedCitations || selectedCitations.has(ref.index))]))
  const chosenNodes = selectedKeys ? extracted.nodes.filter(node => selectedKeys.has(node.key)) : extracted.nodes
  const extraction = {
    nodes: chosenNodes.map(node => {
      const refs = referencesByNode.get(node.key) || []
      if (!refs.length) return node
      const positions = refs.map(ref => `${ref.paper} · ${ref.locator}`)
      return { ...node, excerpt: `原文位置（待核验）：${positions.join('；')}\n${node.excerpt}` }
    }),
    claims: selectedKeys ? extracted.claims.filter(claim => selectedKeys.has(claim.fromKey) && selectedKeys.has(claim.toKey)) : extracted.claims,
    citations: selectedCitations ? extracted.citations.filter((_, index) => selectedCitations.has(index)) : extracted.citations,
  }
  const taxonomyText = `${source} ${extraction.nodes.filter(node => node.kind === 'entity').map(node => node.entityKind).join(' ')}`
  summary.citations = extraction.citations.length
  if (!extraction.nodes.length && !extraction.claims.length && !extraction.citations.length) return summary
  summary.extracted = true

  const origin = { sessionId: summary.sessionId, seq: summary.seq, turn, at: at || now, excerpt: source.trim() }
  const applied = await store.applyExtraction({ nodes: extraction.nodes, claims: extraction.claims, source: origin, project, now })
  summary.addedNodes = applied.addedNodes
  summary.mergedNodes = applied.mergedNodes
  summary.addedClaims = applied.addedClaims
  summary.mergedClaims = applied.mergedClaims

  const touchedByThisMessage = row => (row.sources || []).some(item => item.sessionId === summary.sessionId && item.seq === summary.seq)


  const evidenceIds = new Map()
  for (const [index, citation] of extracted.citations.entries()) {
    if (selectedCitations && !selectedCitations.has(index)) continue
    try {
      const result = await saveEvidence({
        title: citation.title || citation.identifier || citation.url,
        sourceDatabase: DEPOSITION_SOURCE_DATABASE,
        identifier: citation.identifier,
        identifierKind: citation.identifierKind,
        url: traceAnswerSources ? researchCitationHref(citation) : citation.url,
        project,
        tags: autoDepositionTags({ text: `${taxonomyText} ${citation.title || ''}`, identifierKind: citation.identifierKind }),
        reason: `自动沉淀：助手回答中引用的来源（消息 seq ${summary.seq ?? '未知'}），需逐条人工核验。`,
        note: `来源摘录：${(citation.title || '').slice(0, 160)}`,
      })
      if (result?.entry?.id) { evidenceIds.set(index, result.entry.id); summary.savedEvidence++ }
    } catch (error) {
      if (error?.code === 'DUPLICATE') {
        summary.duplicateEvidence++
        if (traceAnswerSources && error.duplicate?.id) evidenceIds.set(index, error.duplicate.id)
      } else summary.failedEvidence++
    }
  }
  if (evidenceIds.size) {
    for (const node of applied.nodes) {
      if (!DEPOSIT_ASSET_KINDS.includes(node.kind) || (selectedKeys && !selectedKeys.has(node.key))) continue
      if (!touchedByThisMessage(node)) continue
      const ids = traceAnswerSources
        ? (referencesByNode.get(node.key) || []).map(ref => evidenceIds.get(ref.index)).filter(Boolean)
        : evidenceIds.values()
      for (const evidenceId of new Set(ids)) await store.linkEvidence(node.id, evidenceId)
    }
  }


  let knownAssetKeys = new Set()
  if (typeof assetProvider?.list === 'function') {
    try {
      knownAssetKeys = new Set(((await assetProvider.list()) || [])
        .map(item => assetDedupeKey(item?.title, item?.project))
        .filter(key => !key.startsWith('::')))
    } catch { knownAssetKeys = new Set() }
  }
  for (const node of applied.nodes) {
    if (!DEPOSIT_ASSET_KINDS.includes(node.kind) || (selectedKeys && !selectedKeys.has(node.key))) continue
    if (!touchedByThisMessage(node)) continue
    const body = node.sources?.[0]?.excerpt || node.label
    const dedupeKey = assetDedupeKey(node.label, project)
    if (!body.trim() || typeof assetProvider?.save !== 'function' || knownAssetKeys.has(dedupeKey)) { summary.skippedAssets++; continue }
    try {
      const asset = await assetProvider.save({
        title: node.label,
        body,
        type: 'insight',
        thinkingKind: DEPOSIT_ASSET_THINKING_KIND[node.kind] || 'conclusion',
        epistemicStatus: 'to_verify',
        verification: { status: 'pending', evidence: '', checkedAt: 0 },
        project,
        tags: autoDepositionTags({ text: `${taxonomyText} ${node.label} ${body}`, kind: node.kind }),
        note: `自动沉淀自助手回答，默认待验证；来源消息：会话 ${summary.sessionId || '本地'} seq ${summary.seq ?? '未知'}。`,
        provenance: { kind: 'auto-deposition', sessionId: summary.sessionId, seq: summary.seq },
      })
      if (asset?.id) {
        await store.setAssetId(node.id, asset.id)
        knownAssetKeys.add(dedupeKey)
        summary.savedAssets++
      } else { summary.skippedAssets++ }
    } catch { summary.skippedAssets++ }
  }

  publishKnowledge()
  if (summary.extracted) latestDepositionSummary = { ...summary, at: now }
  return summary
}




function depositionTextOf(data) {
  const content = data?.message?.content
  if (!Array.isArray(content)) return ''
  return content.filter(block => block?.type === 'text' && typeof block.text === 'string').map(block => block.text).join('\n')
}










function attachKnowledgeDeposition(ctx, { assetProvider } = {}) {
  const sessions = ctx?.sessions
  if (!sessions?.list || typeof sessions?.binding !== 'function') return () => {}
  registerDepositionSessions(sessions)
  let disposeFeed = () => {}
  let boundSessionId = ''
  let queue = Promise.resolve()


  let scannedSeq = 0

  const drain = eventSource => {
    const windowArg = eventSource.getSnapshot()
    const entries = Array.isArray(windowArg?.entries) ? windowArg.entries : []
    if (!entries.length) return




    const fresh = []
    for (let index = entries.length - 1; index >= 0; index--) {
      const seq = Number(entries[index]?.seq)
      if (Number.isFinite(seq) && seq <= scannedSeq) break
      fresh.push(entries[index])
    }
    if (!fresh.length) return
    for (const event of fresh) {
      const seq = Number(event?.seq)
      if (Number.isFinite(seq) && seq > scannedSeq) scannedSeq = seq
    }
    fresh.reverse()
    let cursor = readDepositionCursor(boundSessionId)
    for (const event of fresh) {
      if (!event || event.type !== 'assistant/message') continue
      const seq = Number(event.seq)
      if (!Number.isFinite(seq) || seq <= cursor) continue
      cursor = seq
      const data = event.data || {}
      const text = depositionTextOf(data)

      if (isAutoDepositEnabled() && !data.interrupted && text.length >= MIN_DEPOSITION_MESSAGE_CHARS) {
        const payload = { text, sessionId: boundSessionId, seq, turn: Number(data.turn) || null, at: Number(event.time) || Date.now(), assetProvider }
        queue = queue.then(() => depositAssistantMessage(payload)).catch(() => { /* 单条失败不阻断后续消息 */ })
      }
      writeDepositionCursor(boundSessionId, cursor)
    }
  }

  const rebind = sessionId => {
    if (sessionId === boundSessionId) return
    try { disposeFeed() } catch { /* 旧订阅已失效也继续 */ }
    disposeFeed = () => {}
    boundSessionId = sessionId ? String(sessionId) : ''


    scannedSeq = readDepositionCursor(boundSessionId)
    if (!boundSessionId) return
    let binding = null
    try { binding = sessions.binding(boundSessionId) } catch { return }
    const eventSource = binding?.eventSource
    if (!eventSource || typeof eventSource.getSnapshot !== 'function' || typeof eventSource.subscribe !== 'function') return
    const handle = () => { try { drain(eventSource) } catch { /* 沉淀环节的任何异常都不允许冒泡到宿主 */ } }
    try { disposeFeed = eventSource.subscribe(handle) } catch { disposeFeed = () => {}; return }
    handle()
  }

  const followCurrentSession = () => {
    let current = ''
    try { current = sessions.list.getSnapshot()?.current || '' } catch { /* 会话列表不可读时保持现状 */ }
    rebind(current ? String(current) : '')
  }

  let disposeList = () => {}
  try { disposeList = sessions.list.subscribe(followCurrentSession) } catch { disposeList = () => {} }
  followCurrentSession()
  return () => {
    registerDepositionSessions(null)
    try { disposeList() } catch { /* 已失效 */ }
    try { disposeFeed() } catch { /* 已失效 */ }
  }
}






let depositionSessions = null

function registerDepositionSessions(sessions) {
  depositionSessions = sessions?.list && typeof sessions?.binding === 'function' ? sessions : null
}




function latestDepositableMessage(entries) {
  const list = Array.isArray(entries) ? entries : []
  for (let index = list.length - 1; index >= 0; index--) {
    const event = list[index]
    if (!event || event.type !== 'assistant/message') continue
    const data = event.data || {}
    const text = depositionTextOf(data)
    if (!String(text).trim()) continue
    const seq = Number(event.seq)
    return {
      text,
      seq: Number.isFinite(seq) ? seq : null,
      turn: Number(data.turn) || null,
      at: Number(event.time) || 0,
      interrupted: Boolean(data.interrupted),
    }
  }
  return null
}





async function depositLatestAssistantMessage({
  entries = null,
  sessions,
  sessionId = '',
  store,
  saveEvidence,
  activeProject,
  assetProvider,
} = {}) {
  let windowEntries = entries
  let sid = String(sessionId || '')
  if (!Array.isArray(windowEntries)) {
    const source = sessions !== undefined ? sessions : depositionSessions
    if (!source?.list || typeof source?.binding !== 'function') return { error: 'no-sessions' }
    let current = ''
    try { current = source.list.getSnapshot()?.current || '' } catch { current = '' }
    if (!current) return { error: 'no-session' }
    let eventSource = null
    try { eventSource = source.binding(String(current))?.eventSource || null } catch { eventSource = null }
    const snapshot = typeof eventSource?.getSnapshot === 'function' ? eventSource.getSnapshot() : null
    windowEntries = Array.isArray(snapshot?.entries) ? snapshot.entries : []
    sid = String(current)
  }
  const found = latestDepositableMessage(windowEntries)
  if (!found) return { error: 'empty' }
  const summary = await depositAssistantMessage({
    text: found.text,
    sessionId: sid,
    seq: found.seq,
    turn: found.turn,
    at: found.at,
    assetProvider,
    store,
    saveEvidence,
    activeProject,
  })
  return { summary, seq: found.seq, interrupted: found.interrupted }
}


function readLatestResearchAnswer(sessionId = '') {
  try {
    const sid = String(sessionId || depositionSessions?.list?.getSnapshot()?.current || '')
    if (!sid || !depositionSessions) return null
    const snapshot = depositionSessions.binding(sid)?.eventSource?.getSnapshot?.()
    return latestDepositableMessage(snapshot?.entries)
  } catch { return null }
}



function reviewableAssistantMessage(sessions, sessionId, messageId, chatNodes) {
  const projected = chatNodes?.values?.().find(node => node?.kind === 'turn-tail' && String(node?.data?.closing?.finalNode?.messageId) === String(messageId))
  const closing = projected?.data?.closing
  if (closing) {
    const text = closing.blocks?.filter(block => block?.kind === 'text' && typeof block.text === 'string').map(block => block.text).join('') || ''
    if (text.trim()) return {
      text, seq: Number(closing.finalNode.seq), turn: Number(closing.turn) || null,
      at: Number(closing.finalNode.time) || 0, interrupted: closing.status === 'interrupted', extraction: extractKnowledge(text),
    }
  }
  const entries = readSessionEvents(sessions, sessionId, Infinity)
  const event = entries.findLast(item => item?.type === 'assistant/message' && String(item?.data?.message?.id) === String(messageId))
  const content = event?.data?.message?.content
  if (!Array.isArray(content)) return null
  const text = content.filter(item => item?.type === 'text' && typeof item.text === 'string').map(item => item.text).join('\n')
  if (!text.trim()) return null
  const extraction = extractKnowledge(text)
  return { text, seq: Number(event.seq), turn: Number(event.data?.turn) || null, at: Number(event.time) || 0, interrupted: Boolean(event.data?.interrupted), extraction }
}

function depositPopoverPosition(anchor, viewport, width = 360) {
  if (!anchor || !viewport) return null
  const left = Math.max(12, Math.min(anchor.left, viewport.width - Math.min(width, viewport.width - 24) - 12))
  return anchor.bottom > viewport.height * 0.6
    ? { position: 'fixed', left, bottom: viewport.height - anchor.top + 8 }
    : { position: 'fixed', left, top: anchor.bottom + 8 }
}

function answerClaimText(text) {
  return String(text || '').normalize('NFKC').replace(/[\s\p{P}]+/gu, '').toLowerCase()
}

async function readAnswerClaimCandidates(text, citations, project, signal) {
  const answer = answerClaimText(text)
  const refs = new Set(citations.map(citation => String(citation.identifier || citation.url || '').toLowerCase()))
  const scope = project || 'default'
  const matched = []
  let offset = 0
  let evidenceById = new Map()
  do {
    const query = new URLSearchParams({ project: scope, offset: String(offset) })
    const response = await fetch(`/dsh-research-kit/claim-review?${query}`, { signal })
    const result = await response.json()
    if (!response.ok || !result.ok || !Array.isArray(result.claims)) throw new Error('无法读取课题的论断。')
    if (offset === 0) evidenceById = new Map((result.evidence || []).map(entry => [entry.id, entry]))
    for (const claim of result.claims) {
      const statement = answerClaimText(claim.statement)
      const citation = String(claim.source_ref?.citation || '').toLowerCase()
      if (!claim.id || (claim.project || 'default') !== scope || statement.length < 8
          || !answer.includes(statement) || (citation && !refs.has(citation))) continue
      matched.push(projectClaimProjection(claim, scope))
    }
    if (result.next_offset == null) break
    if (!Number.isInteger(result.next_offset) || result.next_offset <= offset) throw new Error('论断分页响应无效。')
    offset = result.next_offset
  } while (true)
  return { matched, evidenceById }
}

function researchAnswerCandidateSummary(sessions, sessionId, messageId, autoSession) {
  if (!autoSession || !sessionId || !messageId) return null
  const entries = readSessionEvents(sessions, sessionId)
  const answer = entries.findLast(event => event.type === 'assistant/message'
    && String(event.data?.message?.id) === String(messageId))
  if (!answer || !Number.isFinite(Number(answer.seq)) || Number(answer.seq) <= autoSession.afterSeq || answer.data?.interrupted) return null
  const text = answer.data.message.content?.filter(block => block.type === 'text').map(block => block.text).join('\n') || ''
  if (!text.trim()) return null
  const prompt = readSessionEvents(sessions, sessionId, 256).findLast(event => {
    const source = (event.data?.message ?? event.data)?.source
    return event.type === 'user/message' && (!source || source.kind === 'user') && Number(event.seq) < Number(answer.seq)
  })
  const adopted = (prompt?.data?.message ?? prompt?.data)?.content?.some(block => block.type === 'text' && block.text?.includes(RESEARCH_STEPS_HEADING))
  const extracted = extractAnswerEvidence(text)
  const sources = extracted.citations.filter(item => ['doi', 'pmid', 'pmcid', 'arxiv'].includes(item.identifierKind)).length
  const findings = extracted.nodes.filter(node => node.kind === 'finding').length
  if (!adopted && !(sources && (findings || /论文|文献|研究|实验|study|studies|paper|research/i.test(text)))) return null
  return findings || sources ? { findings, sources } : null
}

function ResearchMessageDepositAction({ messageId, sessionId, sessions, assetProvider, useChat }) {
  const chatNodes = typeof useChat === 'function' ? useChat(snapshot => snapshot.nodes) : null
  const anchorRef = React.useRef(null)
  const autoSession = React.useSyncExternalStore(subscribeResearchAutoSessions, () => readResearchAutoSession(sessionId), () => null)
  React.useEffect(() => inheritResearchAutoSession(sessions, sessionId), [sessions, sessionId, messageId])
  const autoCandidate = React.useMemo(() => researchAnswerCandidateSummary(sessions, sessionId, messageId, autoSession),
    [sessions, sessionId, messageId, autoSession, chatNodes])
  const [savedFromAnswer, setSavedFromAnswer] = React.useState(false)
  React.useEffect(() => setSavedFromAnswer(false), [sessionId, messageId])
  const [position, setPosition] = React.useState(null)
  const [preview, setPreview] = React.useState(null)
  const [claimChoices, setClaimChoices] = React.useState(null)
  const [confirmedClaims, setConfirmedClaims] = React.useState([])
  const [claimNotice, setClaimNotice] = React.useState('')
  const associationKey = preview && `dsh-research-kit.answer-claims.v1.${JSON.stringify([sessionId, messageId, preview.project])}`
  React.useEffect(() => {
    if (!preview) return undefined
    const controller = new AbortController()
    const timer = window.setTimeout(() => controller.abort(), 10000)
    try {
      const ids = JSON.parse(window.localStorage.getItem(associationKey) || '[]')
      if (Array.isArray(ids)) setConfirmedClaims(ids)
    } catch { /* 已保存关联无法读取时仍可查看引用。 */ }
    readAnswerClaimCandidates(preview.text, preview.extraction.citations, preview.project, controller.signal)
      .then(result => { if (!controller.signal.aborted) setClaimChoices(result) })
      .catch(() => { if (!controller.signal.aborted || controller.signal.reason?.name === 'AbortError') setClaimNotice('暂时无法读取已有论断。') })
      .finally(() => window.clearTimeout(timer))
    return () => { window.clearTimeout(timer); controller.abort(new Error('回答面板已关闭')) }
  }, [preview, associationKey])
  const [selectedNodes, setSelectedNodes] = React.useState([])
  const [selectedCitations, setSelectedCitations] = React.useState([])
  const [busy, setBusy] = React.useState(false)
  const [notice, setNotice] = React.useState('')
  const place = () => {
    if (typeof window === 'undefined') return
    setPosition(depositPopoverPosition(anchorRef.current?.getBoundingClientRect(), { width: window.innerWidth, height: window.innerHeight }))
  }
  React.useEffect(() => {
    if (!preview && !notice) return undefined
    window.addEventListener('resize', place)
    window.addEventListener('scroll', place, true)
    return () => { window.removeEventListener('resize', place); window.removeEventListener('scroll', place, true) }
  }, [preview, notice])
  React.useEffect(() => {
    if (!notice || preview) return undefined
    const timer = window.setTimeout(() => setNotice(''), 5000)
    return () => window.clearTimeout(timer)
  }, [notice, preview])
  const open = () => {
    place()
    const found = reviewableAssistantMessage(sessions, sessionId, messageId, chatNodes)
    if (!found) { setNotice('当前会话窗口中找不到这条回答。'); return }
    setClaimChoices(null)
    setClaimNotice('')
    setConfirmedClaims([])
    const project = currentResearchContext().project
    const extraction = extractAnswerEvidence(found.text, project)
    setPreview({ ...found, extraction, project })
    setSelectedNodes([])
    setSelectedCitations(extraction.citations.map((_, index) => index))
    setNotice('')
  }
  const toggleClaimAssociation = id => {
    const latest = reviewableAssistantMessage(sessions, sessionId, messageId, chatNodes)
    if (!latest || latest.seq !== preview.seq || latest.text !== preview.text || currentResearchContext().project !== preview.project) {
      setClaimNotice('回答或课题已变化，请重新打开。')
      return
    }
    const ids = confirmedClaims.includes(id) ? confirmedClaims.filter(item => item !== id) : [...confirmedClaims, id]
    try {
      window.localStorage.setItem(associationKey, JSON.stringify(ids))
      setConfirmedClaims(ids)
      setClaimNotice('')
    } catch { setClaimNotice('当前客户端无法保存回答关联。') }
  }
  const toggle = (values, setValues, key) => setValues(values.includes(key) ? values.filter(item => item !== key) : [...values, key])
  const confirm = async () => {
    if (!preview || busy) return
    if (!selectedNodes.length && !selectedCitations.length) { setNotice('请至少选择一项。'); return }
    const latest = reviewableAssistantMessage(sessions, sessionId, messageId, chatNodes)
    if (!latest || latest.seq !== preview.seq || latest.text !== preview.text || currentResearchContext().project !== preview.project) {
      setNotice('回答或课题已变化，请重新打开预览。')
      setPreview(null)
      return
    }
    setBusy(true)
    try {
      const summary = await depositAssistantMessage({
        text: preview.text, sessionId: String(sessionId), seq: preview.seq, turn: preview.turn, at: preview.at,
        selection: { nodeKeys: selectedNodes, citationIndexes: selectedCitations }, traceAnswerSources: true,
        activeProject: preview.project, assetProvider: assetProvider?.(),
      })
      if (summary.extracted) setSavedFromAnswer(true)
      setNotice(summary.extracted ? `已沉淀：知识 ${summary.addedNodes}、证据 ${summary.savedEvidence}、资产 ${summary.savedAssets}；均待人工核验。` : '所选内容没有可提取的研究信息。')
      setPreview(null)
    } catch (error) { setNotice(`沉淀失败：${error?.message || error}`) }
    finally { setBusy(false) }
  }
  const citations = preview?.extraction.citations || []
  const nodes = preview?.extraction.nodes || []
  const evidenceRows = preview?.extraction.rows || []
  const inlineCitations = new Set(evidenceRows.flatMap(row => row.references.map(ref => ref.index)))
  const otherCitations = citations.filter((_, index) => !inlineCitations.has(index))
  const candidateLabel = autoCandidate && !savedFromAnswer
    ? `可保存 ${[autoCandidate.findings && `${autoCandidate.findings} 条结论`, autoCandidate.sources && `${autoCandidate.sources} 条来源`].filter(Boolean).join('、')}`
    : ''
  const matched = claimChoices?.matched || []
  const orderedClaims = [
    ...matched.filter(claim => confirmedClaims.includes(claim.id)),
    ...matched.filter(claim => !confirmedClaims.includes(claim.id)),
  ]
  const sectionStyle = { display: 'grid', gap: 6, paddingBlock: 8, borderTop: `1px solid ${C.line}` }
  const panel = preview ? React.createElement('div', {
    key: 'preview', role: 'group', 'aria-label': '研究回答沉淀预览',
    style: { ...position, zIndex: 2147483000, boxSizing: 'border-box', padding: '10px 12px', width: 'min(360px, calc(100vw - 24px))', maxHeight: 'min(300px, calc(100vh - 72px))',
      overflow: 'auto', border: `1px solid ${C.line}`, borderRadius: 10, color: C.ink, background: C.surface, boxShadow: C.shadowLg, font: `12px/1.45 ${C.font}` },
  }, [
    React.createElement('div', { key: 'head', style: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: 8, paddingBottom: 8 } }, [
      React.createElement('strong', { key: 'title', style: { fontSize: 14 } }, '回答依据'),
      React.createElement(Button, { key: 'close', size: 'sm', variant: 'ghost', 'aria-label': '取消', disabled: busy, onClick: () => setPreview(null) }, '关闭'),
    ]),
    preview.interrupted ? React.createElement('p', { key: 'interrupted', style: { color: C.amber } }, '这条回答曾被中断，内容可能不完整。') : null,
    evidenceRows.length ? React.createElement('section', { key: 'evidence-rows', 'aria-label': '逐条核对结论', style: sectionStyle }, [
      React.createElement('strong', { key: 'title' }, '逐条核对结论'),
      ...evidenceRows.map(row => React.createElement('div', {
        key: row.nodeKey, style: { display: 'grid', gap: 4, paddingBlock: 4, overflowWrap: 'anywhere' },
      }, [
        row.statement ? React.createElement('span', { key: 'finding' }, row.statement) : null,
        ...row.references.map(ref => {
          const citation = citations[ref.index]
          const href = researchCitationHref(citation)
          return React.createElement('div', { key: `${ref.index}:${ref.paper}:${ref.locator}` }, [
            React.createElement(href ? 'a' : 'span', {
              key: 'paper', ...(href ? { href, target: '_blank', rel: 'noopener noreferrer', title: citation.identifier || href } : {}),
              style: { color: href ? C.teal : C.muted },
            }, ref.paper),
            React.createElement('span', { key: 'locator', style: { color: C.muted } }, ` · ${ref.locator}`),
          ])
        }),
        ...row.unlinked.map(ref => React.createElement('span', { key: `${ref.paper}:${ref.locator}`, style: { color: C.muted } },
          `${ref.paper} · ${ref.locator}（标识符缺失或无法识别）`)),
        ...row.gaps.map(gap => React.createElement('span', { key: gap, style: { color: C.amber } }, `证据缺口 · ${gap}`)),
        !row.references.length && !row.unlinked.length && !row.gaps.length
          ? React.createElement('span', { key: 'missing', style: { color: C.muted } }, '回答未提供可定位的来源。') : null,
      ])),
      React.createElement('small', { key: 'state', style: { color: C.muted } }, '出处由回答给出，支持关系待核验。'),
    ]) : null,
    otherCitations.length ? React.createElement('section', { key: 'citations', 'aria-label': '回答引用', style: sectionStyle }, [
      React.createElement('strong', { key: 'title' }, inlineCitations.size ? '其他回答引用' : '回答引用'),
      ...otherCitations.map((citation, index) => {
        const label = citation.identifier || citation.url || citation.title || '来源待核验'
        const href = researchCitationHref(citation)
        return React.createElement(href ? 'a' : 'span', {
          key: index, ...(href ? { href, target: '_blank', rel: 'noopener noreferrer' } : {}),
          style: { overflowWrap: 'anywhere', color: href ? C.teal : C.muted },
        }, label)
      }),
      React.createElement('small', { key: 'state', style: { color: C.muted } }, '引用来自回答，原文与支持关系待核验。'),
    ]) : null,
    orderedClaims.length ? React.createElement('section', { key: 'claims', 'aria-label': '相关论断', style: sectionStyle }, [
      React.createElement('strong', { key: 'title' }, '相关论断'),
      ...orderedClaims.map(claim => React.createElement('div', {
        key: claim.id, style: { display: 'grid', gap: 5 },
      }, [
        React.createElement('span', { key: 'statement', style: { overflowWrap: 'anywhere' } }, claim.statement),
        React.createElement(Button, {
          key: 'link', size: 'sm', variant: 'ghost', onClick: () => toggleClaimAssociation(claim.id), style: { justifySelf: 'start' },
        }, confirmedClaims.includes(claim.id) ? '取消关联' : '关联到此回答'),
        confirmedClaims.includes(claim.id) ? React.createElement(ClaimEvidenceRelations, {
          key: 'sources', claim, evidenceById: claimChoices.evidenceById,
        }) : null,
      ])),
    ]) : null,
    claimNotice ? React.createElement('p', { key: 'claim-notice', role: 'status' }, claimNotice) : null,
    !citations.length && !orderedClaims.length && !evidenceRows.length ? React.createElement('p', { key: 'empty', style: { color: C.muted } }, '这条回答暂无可展示的引用或关联论断。') : null,
    citations.length || nodes.length ? React.createElement('details', { key: 'deposit', style: { borderTop: `1px solid ${C.line}`, paddingTop: 8 } }, [
      React.createElement('summary', { key: 'summary', style: { cursor: 'pointer', fontWeight: 600 } }, '沉淀所选'),
      React.createElement('div', { key: 'choices', style: { display: 'grid', gap: 7, marginTop: 8 } }, [
        ...citations.map((citation, index) => React.createElement('label', { key: `citation-${index}`, style: { overflowWrap: 'anywhere' } }, [
          React.createElement('input', { key: 'check', type: 'checkbox', checked: selectedCitations.includes(index), onChange: () => toggle(selectedCitations, setSelectedCitations, index) }),
          `引用：${citation.identifier || citation.url || citation.title || '来源待核验'}`,
        ])),
        nodes.length ? React.createElement('small', { key: 'candidate-help', style: { color: C.muted } }, '可选的自动抽取候选，请检查后再保存。') : null,
        ...nodes.map(node => React.createElement('label', { key: node.key, style: { overflowWrap: 'anywhere' } }, [
          React.createElement('input', { key: 'check', type: 'checkbox', checked: selectedNodes.includes(node.key), onChange: () => toggle(selectedNodes, setSelectedNodes, node.key) }),
          `${KNOWLEDGE_KIND_LABELS[node.kind] || '知识'}：${node.label}`,
        ])),
        React.createElement(Button, { key: 'confirm', size: 'sm', variant: 'primary', style: { justifySelf: 'start' }, disabled: busy || (!selectedNodes.length && !selectedCitations.length), onClick: confirm }, busy ? '沉淀中…' : '确认沉淀所选'),
        notice ? React.createElement('p', { key: 'deposit-notice', role: 'status' }, notice) : null,
      ]),
    ]) : null,
  ]) : notice ? React.createElement('span', { key: 'notice', role: 'status', style: { ...position, zIndex: 2147483000, display: 'block', boxSizing: 'border-box', padding: '6px 9px', width: 'min(320px, calc(100vw - 24px))', background: '#fff', border: '1px solid #d0d7de', borderRadius: 6, boxShadow: '0 8px 24px rgba(0,0,0,.15)', fontSize: 12 } }, notice) : null
  return React.createElement(React.Fragment, null, [
    React.createElement('button', {
      key: 'open', ref: anchorRef, type: 'button', onClick: open,
      'aria-label': candidateLabel || '审阅并沉淀这条研究回答',
    }, candidateLabel || '回答依据'),
    panel && typeof document !== 'undefined' ? createPortal(panel, document.body) : null,
  ])
}












const QUICK_ENHANCER_POSITION_KEY = 'dsh-research-kit.promptkit.quick-action.position.v1'

const ENHANCER_BUTTON_SIZE = 44
const DEPOSIT_BUTTON_SIZE = 38
const DEPOSIT_BUTTON_GAP = 8

const CLAMP_MIN_X = 16
const CLAMP_MAX_INSET_X = 62
const CLAMP_MIN_Y = 58
const CLAMP_MAX_INSET_Y = 62



function companionDepositPosition(stored, viewport, size = DEPOSIT_BUTTON_SIZE) {
  const width = Math.max(0, Number(viewport?.width) || 0)
  const height = Math.max(0, Number(viewport?.height) || 0)
  const usable = stored && Number.isFinite(Number(stored?.x)) && Number.isFinite(Number(stored?.y))
    ? { x: Number(stored.x), y: Number(stored.y) }
    : { x: Math.max(24, width - 86), y: Math.max(96, height - 158) }
  const anchorX = Math.min(Math.max(CLAMP_MIN_X, usable.x), Math.max(CLAMP_MIN_X, width - CLAMP_MAX_INSET_X))
  const anchorY = Math.min(Math.max(CLAMP_MIN_Y, usable.y), Math.max(CLAMP_MIN_Y, height - CLAMP_MAX_INSET_Y))

  const x = anchorX + (ENHANCER_BUTTON_SIZE - size) / 2
  const above = anchorY - DEPOSIT_BUTTON_GAP - size
  if (above >= CLAMP_MIN_Y) return { x, y: above }
  const below = anchorY + ENHANCER_BUTTON_SIZE + DEPOSIT_BUTTON_GAP
  return { x, y: Math.min(below, Math.max(CLAMP_MIN_Y, height - size - 16)) }
}

const STATUS_TONE_STYLE = {
  ok: { color: C.teal, borderColor: C.tealLine },
  warn: { color: C.amber, borderColor: C.amber },
  busy: { color: C.muted, borderColor: C.line },
}

function ResearchDepositButton() {
  const [position, setPosition] = React.useState(null)
  const [status, setStatus] = React.useState(null)
  const statusTimer = React.useRef(null)

  const measure = React.useCallback(() => {
    if (typeof window === 'undefined' || typeof window.localStorage === 'undefined') return
    let stored = null
    try { stored = JSON.parse(window.localStorage.getItem(QUICK_ENHANCER_POSITION_KEY) || 'null') } catch { stored = null }
    setPosition(companionDepositPosition(stored, { width: window.innerWidth, height: window.innerHeight }))
  }, [])

  React.useEffect(() => {
    measure()

    window.addEventListener('resize', measure)
    window.addEventListener('pointerup', measure)
    return () => {
      window.removeEventListener('resize', measure)
      window.removeEventListener('pointerup', measure)
      if (statusTimer.current) window.clearTimeout(statusTimer.current)
    }
  }, [measure])

  const deposit = async () => {
    if (status?.tone === 'busy') return
    if (statusTimer.current) { window.clearTimeout(statusTimer.current); statusTimer.current = null }
    setStatus({ tone: 'busy', text: '正在沉淀…' })
    let next = null
    try {
      const result = await depositLatestAssistantMessage()
      if (result?.error === 'no-sessions') next = { tone: 'warn', text: '当前环境未提供会话服务' }
      else if (result?.error === 'no-session') next = { tone: 'warn', text: '没有可读取的当前会话' }
      else if (result?.error === 'empty') next = { tone: 'warn', text: '会话里没有可沉淀的回答' }
      else if (!result?.summary?.extracted) next = { tone: 'warn', text: '最近一条回答没有研究内容' }
      else {
        next = {
          tone: 'ok',
          text: `已沉淀：+${result.summary.addedNodes} 节点 · 证据 ${result.summary.savedEvidence} · 资产 ${result.summary.savedAssets}`,
          detail: `消息 #${result.seq ?? '?'}${result.interrupted ? '（曾被中断，内容可能不完整）' : ''}；全部以待核验状态入库，可在「研究证据图谱」分区查看。`,
        }
      }
    } catch (error) {
      next = { tone: 'warn', text: `沉淀失败：${error?.message || error}` }
    }
    setStatus(next)
    statusTimer.current = window.setTimeout(() => setStatus(null), 6000)
  }

  if (!position) return null


  return bodyPortal(h(React.Fragment, null, [
    status ? h('div', {
      key: 'status',
      role: 'status',
      title: status.detail || status.text,
      style: {
        position: 'fixed', left: Math.max(8, position.x - 40), bottom: 'auto',
        top: Math.max(8, position.y - 34), zIndex: 20012,
        maxWidth: 'min(340px, calc(100vw - 24px))',
        padding: '5px 9px', border: `1px solid ${STATUS_TONE_STYLE[status.tone].borderColor}`,
        borderRadius: 8, background: C.surface, boxShadow: C.shadowCard,
        fontSize: 11, lineHeight: 1.45, color: STATUS_TONE_STYLE[status.tone].color,
        whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', pointerEvents: 'none',
      },
    }, status.text) : null,
    h('button', {
      key: 'deposit',
      type: 'button',
      'aria-label': '沉淀当前会话最近一条助手回答',
      title: '把当前会话最近一条助手回答提取入库（本地完成，待核验起步；不开自动沉淀也可用）',
      onClick: deposit,
      style: {
        position: 'fixed', left: position.x, top: position.y, zIndex: 20011,
        width: DEPOSIT_BUTTON_SIZE, height: DEPOSIT_BUTTON_SIZE, padding: 0,
        border: `1px solid ${C.tealLineStrong}`, borderRadius: '50%',
        background: C.tealTint, color: C.teal, cursor: status?.tone === 'busy' ? 'wait' : 'pointer',
        display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
        boxShadow: '0 6px 16px var(--pk-shadow-faint, rgba(15,40,60,.14))',
        transition: 'transform .16s ease, box-shadow .16s ease',
      },
      onMouseEnter: event => { event.currentTarget.style.transform = 'scale(1.06)' },
      onMouseLeave: event => { event.currentTarget.style.transform = 'none' },
    }, h(Icon, { name: 'sparkles', size: 18 })),
  ]))
}











const ARCHIFY_TEMPLATE_PATH = '/dsh-research-kit/archify-template'
let archifyTemplatePromise = null

function loadArchifyTemplate(fetcher = globalThis.fetch) {
  if (archifyTemplatePromise) return archifyTemplatePromise
  if (typeof fetcher !== 'function') return Promise.reject(new Error('当前环境无法加载回放模板。'))
  archifyTemplatePromise = fetcher(ARCHIFY_TEMPLATE_PATH, { headers: { accept: 'text/html' } })
    .then(response => {
      if (!response.ok) throw new Error(`回放模板加载失败（HTTP ${response.status}）`)
      return response.text()
    })
    .catch(error => { archifyTemplatePromise = null; throw error })
  return archifyTemplatePromise
}

const STEP_MS = 620
const EASE = 'cubic-bezier(0.22, 1, 0.36, 1)'


function readTheme() {
  if (typeof document === 'undefined') {
    return { ink: '#17212b', muted: '#607080', line: '#d8e1e8', teal: '#0f766e', amber: '#b45309', canvas: '#f4f7f9', surface: '#fff', tealTint: '#f1faf8', amberTint: '#fff7ed' }
  }
  const style = getComputedStyle(document.body)
  const read = name => style.getPropertyValue(name).trim()
  return {
    ink: read('--rk-ink'), muted: read('--rk-muted'), line: read('--rk-line-strong'),
    teal: read('--rk-teal'), amber: read('--rk-amber'), canvas: read('--rk-canvas'),
    surface: read('--rk-surface'), tealTint: read('--rk-teal-tint'), amberTint: read('--rk-amber-tint'),
  }
}

function prefersReduced() {
  return typeof window !== 'undefined' && window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches
}


function escapeXml(text) {
  return String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;')
}


function traceSegments(trace, prompt) {
  const text = String(prompt || '')
  const nextOccurrence = new Map()
  const anchors = (trace || []).map(step => {
    let needle = null
    if (step.step === 'workflow') return { ...step, anchorStart: 0, anchorEnd: 0, found: true }
    if (step.step === 'guard') needle = '通用科研边界'
    else if (step.step === 'param') needle = String(step.detail || (step.empty ? `[${step.label}]` : '')).slice(0, 16)
    else needle = `【${step.label}】`
    const start = needle ? text.indexOf(needle, nextOccurrence.get(needle) || 0) : -1
    if (start >= 0) nextOccurrence.set(needle, start + needle.length)
    return { ...step, anchorStart: start, anchorEnd: start >= 0 ? start + needle.length : -1, found: start >= 0 }
  })
  const cuts = [0, ...anchors.filter(a => a.found && a.anchorEnd > 0).flatMap(a => [a.anchorStart, a.anchorEnd]).filter(cut => cut > 0 && cut < text.length).sort((a, b) => a - b)]
  const points = [...new Set(cuts)]
  const segments = []
  for (let i = 0; i < points.length; i++) {
    const end = i + 1 < points.length ? points[i + 1] : text.length
    if (end > points[i]) segments.push({ text: text.slice(points[i], end), stepIndex: anchors.findIndex(step => step.found && step.anchorStart <= points[i] && step.anchorEnd >= end && step.anchorEnd > step.anchorStart) })
  }
  return { segments, steps: anchors }
}

const STATION_GLYPH = { workflow: '▶', param: '✎', skill: '✦', database: '⛁', boundary: '⚑', guard: '⚑', step: '·', file: '▤', finding: '✳' }

function buildReplaySvgMarkup(trace = [], theme, { lit = 0, reduced = false } = {}) {
  const gap = 40
  const W = 104, H = 54
  const width = Math.max(W + 8, trace.length * W + (trace.length - 1) * gap + 8)
  const height = 108
  const stationY = 24
  const css = reduced
    ? ''
    : `<style>
.rk-replay-link.lit { stroke: ${theme.teal}; }
.rk-replay-ambient { stroke-dasharray: 0.05 0.12; animation: rk-replay-ambient 1.5s linear infinite; }
@keyframes rk-replay-ambient { to { stroke-dashoffset: -0.34; } }
.rk-replay-comet { stroke-dasharray: 0.16 1; stroke: ${theme.teal}; stroke-width: 2.6; stroke-linecap: round;
  animation: rk-replay-comet-run ${Math.round(STEP_MS * 0.92)}ms ${EASE} forwards; }
@keyframes rk-replay-comet-run { from { stroke-dashoffset: 1.16; opacity: 0.2; } 18% { opacity: 1; } to { stroke-dashoffset: -0.16; opacity: 0; } }
.rk-replay-node.arriving rect { animation: rk-replay-beat ${Math.round(STEP_MS * 0.7)}ms ${EASE} forwards; }
@keyframes rk-replay-beat {
  0% { opacity: 0.55; stroke-width: 1.5; }
  45% { opacity: 1; stroke-width: 2.4; filter: drop-shadow(0 0 7px ${theme.teal}); }
  100% { opacity: 1; stroke-width: 2; filter: drop-shadow(0 0 3px ${theme.teal}); }
}
</style>`
  let parts = []
  let x = 4
  trace.forEach((step, i) => {
    const isBoundary = step.step === 'boundary' || step.step === 'guard'
    if (i > 0) {
      const x1 = x - gap + 6, x2 = x - 6, y1 = stationY + H / 2
      const mid = (x1 + x2) / 2
      const linkLit = lit > i
      const linkClass = linkLit ? (reduced ? 'rk-replay-link lit-static' : 'rk-replay-link lit') : 'rk-replay-link'
      const linkStroke = linkLit && reduced ? theme.teal : theme.line
      parts.push(`<path class="${linkClass}" data-step="${i}" d="M ${x1} ${y1} C ${mid} ${y1}, ${mid} ${y1}, ${x2} ${y1}" stroke="${linkStroke}" stroke-width="1.8" fill="none" pathLength="1"/>`)
      if (linkLit && !reduced) {
        parts.push(`<path class="rk-replay-ambient" d="M ${x1} ${y1} C ${mid} ${y1}, ${mid} ${y1}, ${x2} ${y1}" stroke="${theme.teal}" stroke-width="2.2" fill="none" pathLength="1" opacity="0.85"/>`)
      }
      if (lit - 1 === i && !reduced) {
        parts.push(`<path class="rk-replay-comet" data-step="${i}" d="M ${x1} ${y1} C ${mid} ${y1}, ${mid} ${y1}, ${x2} ${y1}" fill="none" pathLength="1"/>`)
      }
    }
    const isLit = lit > i
    const arriving = lit - 1 === i && !reduced
    const fill = isBoundary ? theme.amberTint : step.step === 'skill' || step.step === 'database' ? theme.tealTint : theme.surface
    const accent = isBoundary ? theme.amber : theme.teal
    const stroke = step.step === 'workflow' ? accent : isLit ? accent : theme.line
    const dash = step.empty ? ' stroke-dasharray="4 3"' : ''
    parts.push(`<g class="rk-replay-node${isLit ? ' lit' : ''}${arriving ? ' arriving' : ''}" data-step="${i}">`)
    parts.push(`<rect x="${x}" y="${stationY}" width="${W}" height="${H}" rx="12" fill="${fill}" stroke="${stroke}" stroke-width="${isLit ? 2 : 1.5}"${dash}/>`)
    parts.push(`<rect x="${x}" y="${stationY}" width="${W}" height="4" rx="2" fill="${accent}" opacity="${isLit ? 0.95 : 0.35}"/>`)
    parts.push(`<text x="${x + 10}" y="${stationY + 22}" font-size="10" fill="${accent}">${escapeXml(STATION_GLYPH[step.step] || '·')} ${i + 1}</text>`)
    parts.push(`<text x="${x + 10}" y="${stationY + 38}" font-size="11.5" font-weight="600" fill="${theme.ink}">${escapeXml(String(step.label).slice(0, 8))}</text>`)
    parts.push(`<text x="${x + 10}" y="${stationY + 51}" font-size="9.5" fill="${theme.muted}">${escapeXml(String(step.detail || '').slice(0, 12))}</text>`)
    if (step.empty) parts.push(`<text x="${x + W - 26}" y="${stationY + 22}" font-size="9" fill="${theme.amber}">待填</text>`)
    parts.push(`</g>`)
    x += W + gap
  })
  const current = lit > 0 && lit <= trace.length ? trace[lit - 1] : null
  const caption = current ? `${lit}/${trace.length} · ${current.label} — ${current.detail}` : ''
  const markup = `<svg class="rk-replay-svg" xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="img" aria-label="组装回放路线">${css}<defs><clipPath id="rk-replay-clip"><rect width="${width}" height="${height}" rx="12"/></clipPath></defs><rect width="${width}" height="${height}" fill="${theme.canvas}"/><g clip-path="url(#rk-replay-clip)">${parts.join('')}</g></svg>`
  return { markup, width, height, caption }
}

function RouteReplay({ trace, prompt }) {
  const reducedInitial = prefersReduced()
  const [still, setStill] = React.useState(reducedInitial)
  const [lit, setLit] = React.useState(0)
  const theme = readTheme()
  const total = (trace || []).length
  React.useEffect(() => { setLit(still ? total : Math.min(1, total)) }, [trace, still, total])
  React.useEffect(() => {
    if (still || lit === 0 || lit >= total) return
    const timer = setTimeout(() => setLit(current => Math.min(total, current + 1)), STEP_MS)
    return () => clearTimeout(timer)
  }, [lit, still, total])
  const play = () => { setLit(0); requestAnimationFrame(() => setLit(Math.min(1, total))) }
  const { segments } = React.useMemo(() => traceSegments(trace, prompt), [trace, prompt])
  const { markup, caption } = buildReplaySvgMarkup(trace, theme, { lit, reduced: still })
  const exportSnapshot = () => {
    const { markup: full } = buildReplaySvgMarkup(trace, theme, { lit: total, reduced: true })
    const html = `<!doctype html><meta charset="utf-8"><title>组装回放快照</title><style>body{margin:0;padding:24px;background:${theme.canvas};color:${theme.ink};font:14px system-ui}h1{font-size:16px;margin:0 0 6px}p{margin:0 0 14px;color:${theme.muted};font-size:12px}</style><h1>组装回放快照</h1><p>本快照只记录一次真实的 Prompt 组装事实（工作流、参数、附加技能、数据源边界），不表示工作流已被执行；结果需人工核验。</p>${full}`
    downloadText(html, 'text/html', 'route-replay-snapshot.html')
  }
  const litSet = new Set(Array.from({ length: lit }, (_, i) => i))
  return h('div', { className: 'rk-replay', style: { border: `1px solid ${C.line}`, borderRadius: 12, padding: 12, background: C.surface, display: 'grid', gap: 10 } }, [
    h('div', { key: 'head', style: { display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap' } }, [
      h('strong', { key: 't', style: { fontSize: 13 } }, '组装回放'),
      h('span', { key: 'h', style: { fontSize: 12, color: C.muted } }, '只回放本次真实的组装事实；发送与执行由你完成，结果需人工核验。'),
      h('span', { key: 'sp', style: { flex: 1 } }),
      h('button', {
        key: 'popup', type: 'button',
        onPointerEnter: () => { loadArchifyTemplate().catch(() => {}) },
        onFocus: () => { loadArchifyTemplate().catch(() => {}) },
        onClick: () => openReplayWindow(trace, '组装回放'),
        style: buttonStyle(C),
      }, '弹出回放窗口'),
      h('button', { key: 'mode', type: 'button', onClick: () => setStill(value => !value), style: buttonStyle(C) }, still ? '切到动画' : '切到静态'),
      !still ? h('button', { key: 'play', type: 'button', onClick: play, style: buttonStyle(C) }, '重新播放') : null,
      h('button', { key: 'export', type: 'button', onClick: exportSnapshot, style: buttonStyle(C) }, '导出快照'),
    ]),
    h('div', { key: 'svg', style: { overflowX: 'auto' }, dangerouslySetInnerHTML: { __html: markup } }),
    caption ? h('div', { key: 'caption', style: { fontSize: 12, color: C.teal, fontWeight: 600 } }, caption) : null,
    h('div', { key: 'prompt', style: { maxHeight: 200, overflow: 'auto', border: `1px solid ${C.line}`, borderRadius: 10, padding: 10, fontSize: 12, lineHeight: 1.6, whiteSpace: 'pre-wrap', fontFamily: 'ui-monospace, monospace' } },
      segments.map((seg, i) => h('span', {
        key: i,
        style: seg.stepIndex >= 0 && litSet.has(seg.stepIndex)
          ? { background: C.tealTint, outline: `1px solid ${C.tealLineStrong}`, borderRadius: 3 }
          : null,
      }, seg.text)),
    ),
    h('div', { key: 'legend', style: { fontSize: 11, color: C.muted } },
      `共 ${total} 站；已点亮 ${Math.min(lit, total)} 站。${still ? '静态模式。' : ''}`),
  ])
}

function buttonStyle(C) {
  return { fontSize: 12, padding: '4px 10px', borderRadius: 8, border: `1px solid ${C.line}`, background: C.surface, color: C.ink, cursor: 'pointer' }
}




async function openReplayWindow(trace, title) {
  if (typeof window === 'undefined') return null

  const popup = window.open('', '_blank')
  if (!popup) { alert('弹窗被浏览器拦截；请允许本站弹窗后重试。'); return null }
  popup.document.write('<!doctype html><meta charset="utf-8"><title>正在加载组装回放…</title><p style="font:14px system-ui;padding:24px">正在加载组装回放…</p>')
  popup.document.close()
  let template
  try {
    template = await loadArchifyTemplate()
  } catch (error) {
    if (popup.closed) return null
    popup.document.open()
    popup.document.write(`<!doctype html><meta charset="utf-8"><title>回放加载失败</title><p style="font:14px system-ui;padding:24px">${escapeXml(error?.message || error)}</p>`)
    popup.document.close()
    return popup
  }
  if (popup.closed) return null
  const steps = (trace || [])
  const nodes = archifyLayoutRow(steps.map((step, i) => ({
    id: `s${i}`,
    kind: step.step === 'guard' ? 'boundary' : step.step === 'workflow' ? 'workflow' : step.step,
    label: step.label,
    note: step.detail,
  })), { y: 60, gap: 48 })
  const edges = []
  for (let i = 1; i < nodes.length; i++) edges.push({ id: `e${i}`, from: nodes[i - 1].id, to: nodes[i].id })
  const svg = buildArchifySvg({
    nodes, edges,
    title: title || '组装回放',
    subtitle: '本窗口只回放一次真实的 Prompt 组装事实；不表示工作流已被执行，结果需人工核验。',
    locale: 'zh-CN', preset: 'classic', animation: 'trace',
  })
  const guidedViews = nodes.length ? [{ id: 'replay', label: '组装回放路线', focus: nodes.map(n => n.id) }] : []
  const html = archifyApplyTemplate({
    template,
    title: title || '组装回放',
    subtitle: '只回放真实的组装事实；发送与执行由你完成，结果需人工核验。',
    svg,
    cards: [
      { dot: 'cyan', title: '组装事实', items: steps.map(step => `${step.label}: ${step.detail}${step.empty ? '（待填）' : ''}`) },
      { dot: 'amber', title: '使用边界', items: ['本窗口不预测执行结果', '发送后由会话 Agent 执行', '产出需人工核验后采用'] },
    ],
    locale: 'zh-CN',
    visualPreset: 'classic',
    guidedViews,
  })
  popup.document.open()
  popup.document.write(html)
  popup.document.close()
  return popup
}



