    try {
      window.localStorage.removeItem(PROMPTKIT_LOAD_ERROR_KEY)
      window.localStorage.setItem(PROMPTKIT_LOADED_KEY, new Date().toISOString())
    } catch { /* 存储不可用时无痕放弃 */ }
