function ResearchKitDiagnosticsAction({ subject }) {
  const [state, setState] = React.useState('idle')
  const timer = React.useRef(null)
  React.useEffect(() => () => { if (timer.current) clearTimeout(timer.current) }, [])
  if (!isResearchBundle(subject)) return null
  const settle = next => {
    if (timer.current) clearTimeout(timer.current)
    setState(next)
    timer.current = setTimeout(() => setState('idle'), 2000)
  }
  const copy = () => {
    if (state === 'busy') return
    setState('busy')
    fetchHostCapabilities()
      .then(capabilities => navigator.clipboard.writeText(JSON.stringify(
        researchKitDiagnosticsPayload({ capabilities, userAgent: navigator.userAgent || '' }), null, 2)))
      .then(() => settle('done'))
      .catch(() => settle('failed'))
  }
  const label = state === 'busy' ? '复制中…' : state === 'done' ? '已复制' : state === 'failed' ? '复制失败' : '复制诊断'
  return h(React.Fragment, null, [
    h(GlobalStyle, { key: 'style' }),
    h(Button, {
      key: 'copy', size: 'sm', variant: 'ghost', icon: state === 'done' ? 'check' : 'copy',
      disabled: state === 'busy', onClick: copy,
      title: '复制插件版本、目录规模与宿主能力探测结果，便于反馈问题；只写入本机剪贴板，不会上传。',
    }, label),
  ])
}





const RESEARCH_KIT_CONSOLE_VIEW = 'dsh-research-kit-console'













function researchKitOpenWorkbench(open) {
  if (typeof open !== 'function') return false
  try { return open() !== false } catch { return false }
}








const RESEARCH_KIT_CONFIG_PRESETS = [
  {
    id: 'direct', label: '直连研究',
    description: '仅使用直查适配器；查询不可用时不委托给 Agent。',
    values: { memoryServer: 'memory-center', memoryTimeoutMs: 5000, databaseTimeoutMs: 10000, databaseRequestsPerMinute: 6, allowAgentFallback: false },
  },
  {
    id: 'assisted', label: 'Agent 辅助',
    description: '保留默认超时、速率和 Agent 回退。',
    values: { memoryServer: 'memory-center', memoryTimeoutMs: 15000, databaseTimeoutMs: 15000, databaseRequestsPerMinute: 12, allowAgentFallback: true },
  },
]


function researchKitPresetOps(presetId, presets = RESEARCH_KIT_CONFIG_PRESETS) {
  const preset = presets.find(candidate => candidate.id === presetId)
  if (!preset) return null
  return Object.entries(preset.values).map(([field, value]) => ({ op: 'set', path: [field], value }))
}


function ResearchKitPresetConfig({ view, form }) {
  const [state, setState] = React.useState('idle')
  if (view === 'summary') return '选择直连研究或 Agent 辅助配置。'
  if (!form || form.state.status !== 'ready') return null
  const apply = async preset => {
    if (!form.state.writable || state === 'busy') return
    setState('busy')
    try {
      const accepted = await form.mutate(researchKitPresetOps(preset.id), form.state.revision)
      setState(accepted ? preset.id : 'failed')
    } catch {
      setState('failed')
    }
  }
  return h('section', { style: { display: 'grid', gap: 10, marginTop: 12 } }, [
    h('p', { key: 'hint', style: { margin: 0, color: C.muted, fontSize: 13, lineHeight: 1.5 } }, '预设会原子覆盖全部 Research Kit 运行字段；手动字段仍可在下方调整。'),
    ...RESEARCH_KIT_CONFIG_PRESETS.map(preset => h('div', { key: preset.id, style: { display: 'flex', gap: 10, alignItems: 'center', justifyContent: 'space-between', padding: '10px 12px', border: `1px solid ${C.line}`, borderRadius: 10 } }, [
      h('div', { key: 'text' }, [h('strong', { key: 'label', style: { fontSize: 13 } }, preset.label), h('div', { key: 'description', style: { color: C.muted, fontSize: 12, marginTop: 3 } }, preset.description)]),
      h(Button, { key: 'apply', size: 'sm', variant: 'ghost', disabled: !form.state.writable || state === 'busy', onClick: () => { void apply(preset) } }, state === preset.id ? '已应用' : '应用'),
    ])),
    state === 'failed' ? h('p', { key: 'failed', style: { margin: 0, color: C.amber, fontSize: 12 } }, '预设未保存；请检查配置页的错误提示后重试。') : null,
  ])
}







function ResearchKitOpenWorkbenchAction({ subject, open }) {
  const [denied, setDenied] = React.useState(false)
  const timer = React.useRef(null)
  React.useEffect(() => () => { if (timer.current) clearTimeout(timer.current) }, [])
  if (!isResearchBundle(subject)) return null
  if (typeof open !== 'function') return null
  const handle = () => {
    if (researchKitOpenWorkbench(open)) return
    if (timer.current) clearTimeout(timer.current)
    setDenied(true)
    timer.current = setTimeout(() => setDenied(false), 2000)
  }
  return h(React.Fragment, null, [
    h(GlobalStyle, { key: 'style' }),
    h(Button, {
      key: 'open', size: 'sm', variant: 'ghost', icon: 'layers', onClick: handle,
      title: '把主区切回当前会话；该会话此前停在科研工作台时会一并恢复该视图。宿主未提供会话导航服务时不显示此按钮。',
    }, denied ? '暂不可用' : '回到会话'),
  ])
}



const TRANSFER_SECTIONS = [
  ['evidence', '证据'], ['claims', '论断'], ['links', '资产关联'], ['ledger', '筛选账本'],
  ['workspaces', '课题设置'], ['knowledgeNodes', '知识节点'], ['knowledgeClaims', '知识关系'],
  ['assets', '灵感资产'], ['runs', '研究运行'],
]

function transferDownload(text, name) {

  return downloadJsonFile(text, name, { revokeDelayMs: 10_000 })
}

async function captureResearchTransfer(assetProvider) {
  if (!assetProvider?.list || !assetProvider?.save) throw new Error('灵感资产服务尚未就绪。')
  const synced = await syncEvidenceVaultWithFiles('', { force: true, pullOnly: true })
  const evidence = evidenceVaultStore()
  await synchronizeClaimScopes(evidence)
  const knowledge = knowledgeStore()
  const [entries, claims, links, ledger, workspaces, nodes, knowledgeClaims, assets] = await Promise.all([
    evidence.list(), evidence.listResearchClaims(), evidence.listAssetEvidenceLinks(),
    evidence.listResearchLedger(), evidence.listWorkspaces({ includeArchived: true }),
    knowledge.listNodes(), knowledge.listClaims(), assetProvider.list(),
  ])
  if (evidence.isDegraded() || knowledge.isDegraded()) throw new Error('本地数据库不可用；为防止只迁移到临时内存，已停止。')
  if (synced.skipped) throw new Error('文件同步不可用；为防止遗漏 Agent 保存的证据，已停止。')
  const evidenceBackup = JSON.parse(serializeEvidenceBackup({ entries, claims, links, ledger,
    workspaces: workspaces.filter(row => row.origin === 'user' || row.updatedAt > 0) }))
  const knowledgeBackup = JSON.parse(serializeKnowledgeBackup({ nodes, claims: knowledgeClaims }))

  evidenceBackup.exportedAt = 0
  knowledgeBackup.exportedAt = 0
  return {
    evidence: evidenceBackup,
    knowledge: knowledgeBackup,
    assets, runs: listResearchRuns(),
  }
}

async function applyResearchTransfer(incoming, current, assetProvider, progress) {
  const store = evidenceVaultStore()
  const existing = current.evidence.entries
  const merged = mergeEntries(existing, incoming.evidence.entries)
  const addedEntries = merged.rows.filter(row => !existing.some(item => item.id === row.id))
  progress('正在导入证据与课题…')
  if (addedEntries.length) await store.importMany(addedEntries)
  await store.importWorkspaces(incoming.evidence.workspaces)

  progress('正在导入灵感资产…')
  const assetIds = new Set(current.assets.map(item => item.id))
  for (const item of incoming.assets) {
    if (assetIds.has(item.id)) continue
    await assetProvider.save(item)
    assetIds.add(item.id)
  }

  progress('正在恢复证据关联与账本…')
  const evidenceIds = new Set((await store.list()).map(item => item.id))
  let skippedRelated = 0
  const claimIds = new Set(current.evidence.claims.map(item => item.id))
  for (const item of incoming.evidence.claims) {
    if (claimIds.has(item.id)) continue
    if (item.links?.some(link => !evidenceIds.has(link.evidenceId))) { skippedRelated++; continue }
    await store.saveResearchClaim(item)
    claimIds.add(item.id)
  }
  const linkIds = new Set(current.evidence.links.map(item => item.id))
  for (const item of incoming.evidence.links) {
    if (linkIds.has(item.id)) continue
    if (!evidenceIds.has(item.evidenceId) || !assetIds.has(item.assetId)) { skippedRelated++; continue }
    await store.linkAssetEvidence(item)
    linkIds.add(item.id)
  }
  const ledgerIds = new Set(current.evidence.ledger.map(item => item.id))
  for (const item of incoming.evidence.ledger) {
    if (ledgerIds.has(item.id)) continue
    if (item.kind === 'screening' && !evidenceIds.has(item.evidenceId)) { skippedRelated++; continue }
    await store.saveResearchLedgerEvent(item)
    ledgerIds.add(item.id)
  }

  progress('正在导入知识与研究运行…')
  await knowledgeStore().importBackup(incoming.knowledge)
  importResearchRuns(incoming.runs)
  progress('正在同步文件侧证据…')
  invalidateEvidenceSync()
  const synced = await syncEvidenceVaultWithFiles('', { force: true, allowExistingSources: true })
  await synchronizeClaimScopes(store)
  publishEvidenceVault()
  publishKnowledge()
  return { addedEvidence: addedEntries.length, skippedEvidence: merged.skipped, invalidEvidence: merged.invalid,
    skippedRelated, existingSources: synced.existingSources || 0 }
}

function ResearchTransferPanel({ assetProvider, onClose }) {
  const [incoming, setIncoming] = React.useState(null)
  const [preview, setPreview] = React.useState(null)
  const [baseline, setBaseline] = React.useState(null)
  const [backupReady, setBackupReady] = React.useState(false)
  const [busy, setBusy] = React.useState(false)
  const [notice, setNotice] = React.useState('')
  const [progress, setProgress] = React.useState('')

  const exportCurrent = async () => {
    setBusy(true)
    try {
      const data = await captureResearchTransfer(assetProvider)
      transferDownload(await serializeResearchTransfer(data), `research-kit-app-transfer-${Date.now()}.json`)
      setNotice('已生成完整迁移包。请妥善保管；它包含笔记、灵感资产及来源摘录。')
    } catch (error) { setNotice(`导出失败：${error?.message || error}`) }
    finally { setBusy(false) }
  }
  const selectFile = async event => {
    setIncoming(null); setPreview(null); setBaseline(null); setBackupReady(false)
    const file = event.target.files?.[0]
    if (!file) return
    if (file.size > 30_000_000) return setNotice('迁移文件超过 30 MB；请分批导出或联系维护者。')
    setBusy(true)
    try {
      const data = await parseResearchTransfer(await file.text())
      const current = await captureResearchTransfer(assetProvider)
      setIncoming(data)
      setPreview(previewResearchTransfer(data, current))
      setBaseline(JSON.stringify(current))
      setNotice('校验通过。请检查预览，先下载本端备份，再确认增量导入。已有 ID 不覆盖。')
    } catch (error) { setNotice(`预览失败：${error?.message || error}`) }
    finally { setBusy(false); event.target.value = '' }
  }
  const backupCurrent = async () => {
    setBusy(true)
    try {
      const current = await captureResearchTransfer(assetProvider)
      if (JSON.stringify(current) !== baseline) throw new Error('本端数据已变化，请重新选择迁移文件并预览。')
      transferDownload(await serializeResearchTransfer(current), `research-kit-before-import-${Date.now()}.json`)
      setBackupReady(true)
      setNotice('已生成本端导入前备份。确认文件已保存后，再点击“确认增量导入”。')
    } catch (error) { setBackupReady(false); setNotice(`备份失败：${error?.message || error}`) }
    finally { setBusy(false) }
  }
  const apply = async () => {
    if (!incoming || !backupReady) return
    setBusy(true)
    try {
      const current = await captureResearchTransfer(assetProvider)
      if (JSON.stringify(current) !== baseline) throw new Error('本端数据已变化，未导入；请重新选择迁移文件并预览。')
      if (current.runs.length + preview.runs.add > MAX_RESEARCH_RUNS) throw new Error(`合并后研究运行超过 ${MAX_RESEARCH_RUNS} 条上限，已停止；请先备份并整理旧运行。`)
      const result = await applyResearchTransfer(incoming, current, assetProvider, setProgress)
      setNotice(`导入完成：新增证据 ${result.addedEvidence} 条，跳过已有 ${result.skippedEvidence} 条，拒收无效 ${result.invalidEvidence} 条，未恢复关联 ${result.skippedRelated} 条。${result.existingSources ? `文件侧已有同源证据 ${result.existingSources} 条，未覆盖原记录；` : ''}其余数据按稳定 ID 增量合并，请刷新核对。`)
      setIncoming(null); setPreview(null); setBackupReady(false)
    } catch (error) { setNotice(`导入未完成：${error?.message || error}。原数据未清空；可用导入前备份核对，重新预览后续导。`) }
    finally { setBusy(false); setProgress('') }
  }

  return h(Card, { style: { margin: '12px var(--rk-gutter)', display: 'grid', gap: 10, maxWidth: 780 } }, [
    h('div', { key: 'head', style: { display: 'flex', justifyContent: 'space-between', gap: 8, flexWrap: 'wrap' } }, [
      h('strong', { key: 'title' }, '迁移到 DSH App'),
      h(Button, { key: 'close', size: 'sm', variant: 'ghost', onClick: onClose }, '关闭'),
    ]),
    h('p', { key: 'hint', style: { margin: 0, color: C.muted, fontSize: 12 } }, '在旧 Web 端导出迁移包；在 App 中选择该文件，预览后增量导入。两端页面源不同，不会自动共享浏览器数据。'),
    h('div', { key: 'actions', style: { display: 'flex', gap: 8, flexWrap: 'wrap' } }, [
      h(Button, { key: 'export', size: 'sm', disabled: busy, onClick: exportCurrent }, '导出本端完整迁移包'),
      h('label', { key: 'file', style: { display: 'inline-grid', gap: 4, fontSize: 12, color: C.ink } }, [
        '选择迁移文件', h('input', { key: 'input', type: 'file', accept: '.json,application/json', disabled: busy, onChange: selectFile, 'aria-label': '选择 Research Kit 迁移文件' }),
      ]),
    ]),
    preview ? h('div', { key: 'preview', role: 'status', style: { display: 'grid', gap: 4, fontSize: 12 } }, [
      h('strong', { key: 'label' }, '导入预览（总数／预计新增／本端已有）'),
      ...TRANSFER_SECTIONS.map(([key, label]) => h('div', { key }, `${label}：${preview[key].total}／${preview[key].add}／${preview[key].existing}${preview[key].invalid ? `（无效 ${preview[key].invalid}）` : ''}`)),
      h('div', { key: 'confirm', style: { display: 'flex', gap: 8, flexWrap: 'wrap', marginTop: 6 } }, [
        h(Button, { key: 'backup', size: 'sm', disabled: busy, onClick: backupCurrent }, '先下载本端备份'),
        h(Button, { key: 'apply', size: 'sm', variant: 'primary', disabled: busy || !backupReady, onClick: apply }, '确认增量导入'),
      ]),
    ]) : null,
    progress ? h('span', { key: 'progress', role: 'status', style: { color: C.teal } }, progress) : null,
    notice ? h(Notice, { key: 'notice', tone: notice.includes('失败') || notice.includes('未完成') ? 'error' : 'info' }, notice) : null,
  ])
}



const HOME_RUN_LABELS = { draft: '提示词草稿', active: '已发送到会话', waiting_review: '待人工审核', completed: '已完成', failed: '失败' }

function ResearchProjectHome({ onNavigate, insertMaterialReference, inputActions }) {
  const [context, setContext] = React.useState(currentResearchContext)
  const [loaded, setData] = React.useState(null)
  const [error, setError] = React.useState('')
  const [draftFeedback, setDraftFeedback] = React.useState('')
  const [projectEditor, setProjectEditor] = React.useState(null)
  const [externalRunId, setExternalRunId] = React.useState('')
  const [runAction, setRunAction] = React.useState(false)
  const [runFeedback, setRunFeedback] = React.useState('')
  const run = activeResearchRun()
  const scopedRun = run?.project === context.project ? run : null
  const activeRunId = scopedRun?.id || (run ? '' : context.activeRunId)
  const version = React.useRef(0)
  React.useEffect(() => subscribeResearchContext(setContext), [])
  const refresh = React.useCallback(async () => {
    const request = ++version.current
    const store = evidenceVaultStore()
    let syncError = ''
    try {
      await syncEvidenceVaultWithFiles(context.project || undefined).catch(failure => { syncError = `文件同步失败：${failure.message}` })
      const [counts, ledger, claims] = await Promise.all([
        store.evidenceSummary({ project: context.project }),
        store.listResearchLedger({ project: context.project }),
        synchronizeResearchClaims(store, context.project).then(result => result.claims)
          .catch(failure => { syncError += ` Claim 台账暂不可达：${failure.message}`; return store.listResearchClaims({ project: context.project }) }),
      ])
      const runClaims = activeRunId ? claims.filter(claim => claim.run_id === activeRunId) : claims
      const missing = new Set()
      if (runClaims.some(claim => claim.links?.length)) {
        const ids = new Set((await store.list({ project: context.project })).map(entry => entry.id))
        for (const claim of runClaims) {
          for (const link of claim.links || []) if (!ids.has(link.evidenceId)) missing.add(link.evidenceId)
        }
      }
      let activity = null
      if (activeRunId) {
        const params = new URLSearchParams({ run_id: activeRunId, limit: '30' })
        try {
          const response = await fetch(`/dsh-research-kit/agent-activity?${params}`, { signal: AbortSignal.timeout(5000) })
          activity = await response.json()
          if (!response.ok || !activity.ok) throw new Error(activity.error || `HTTP ${response.status}`)
        } catch (failure) { syncError += ` 运行状态暂不可达：${failure.message}`; activity = null }
      }
      if (request !== version.current) return
      setData({ counts, ledger, claims, activity, missing, project: context.project, runId: activeRunId }); setError(syncError)
    } catch (failure) { if (request === version.current) setError(`读取失败，保留上次数据：${failure.message}`) }
  }, [context.project, activeRunId])
  React.useEffect(() => { refresh(); const dispose = subscribeEvidenceVault(refresh); return () => { version.current++; dispose() } }, [refresh])
  const data = loaded?.project === context.project && loaded?.runId === activeRunId ? loaded : null
  const projectRuns = listResearchRuns({ project: context.project }).sort((a, b) => b.createdAt - a.createdAt)
  const recentRun = projectRuns[0]
  const scopedClaims = activeRunId ? (data?.claims || []).filter(claim => claim.run_id === activeRunId) : data?.claims || []
  const pending = scopedClaims.filter(claim => !['verified', 'rejected'].includes(claim.state)).length
  const question = scopedClaims.find(claim => claim.question)?.question || data?.claims.find(claim => claim.question)?.question
  const overview = data?.activity?.run_overview
  const checkpoints = data?.activity?.checkpoints || []
  const pendingStages = overview?.passport_found && overview.project !== (context.project || 'default')
    ? []
    : overview?.checkpoint_state?.pending || checkpoints.filter(cp => cp.run_id === activeRunId)
      .flatMap(cp => Object.entries(cp.checkpoints || {}).filter(([, checkpoint]) => !checkpoint.approved).map(([stage]) => stage))
  const outputs = (data?.ledger || []).filter(event => event.kind === 'artifact' && (!activeRunId || event.runId === activeRunId)).slice(0, 3)
  const activityOutputs = data?.activity?.artifacts || []
  const openProjectEditor = () => {
    setProjectEditor(previous => previous === null ? context.project : null)
    setExternalRunId('')
    setRunFeedback('')
  }
  const bindRun = async event => {
    event.preventDefault()
    const id = externalRunId.trim()
    if (!id || runAction) return
    setRunAction(true)
    setRunFeedback('')
    try {
      const params = new URLSearchParams({ run_id: id, limit: '1' })
      const response = await fetch(`/dsh-research-kit/agent-activity?${params}`, { signal: AbortSignal.timeout(5000) })
      const activity = await response.json()
      if (!response.ok || !activity.ok) throw new Error('无法读取运行，请检查运行 ID 后重试。')
      const found = activity.run_overview
      if (!found?.passport_found || found.run_id !== id || found.project !== (context.project || 'default')) throw new Error('当前课题中找不到该运行，请核对课题和运行 ID。')
      if (currentResearchContext().project !== context.project) return
      setResearchContext({ activeRunId: id })
      setProjectEditor(null)
      setExternalRunId('')
    } catch (failure) { setRunFeedback(failure.message) }
    finally { setRunAction(false) }
  }
  const approveStage = async stage => {
    if (!activeRunId || runAction) return
    setRunAction(true)
    setRunFeedback('')
    try {
      const response = await fetch('/dsh-research-kit/agent-activity', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'research_run_checkpoint_approve', run_id: activeRunId, stage }),
        signal: AbortSignal.timeout(5000),
      })
      const result = await response.json()
      if (!response.ok || !result.ok) throw new Error(result.error || `HTTP ${response.status}`)
      if (currentResearchContext().activeRunId === activeRunId) await refresh()
    } catch (failure) { setRunFeedback(`阶段确认失败：${failure.message}`) }
    finally { setRunAction(false) }
  }
  const restore = id => {
    setDraftFeedback('')
    if (!resumeResearchRun(id, context.project)) setError('研究运行已变更，请刷新项目状态。')
  }
  const prepareContinuation = () => {
    const prompt = [
      `继续科研运行 ${activeRunId}，研究项目：${context.project || 'default'}。`,
      '先用 research_run_status 查看进度，再用 research_context_pack 读取现有论断、证据和回执。后续记录沿用这个 run_id。',
      scopedRun?.workflowId
        ? `若没有状态护照，核对材料后用 research_run_start，以工作流 ${scopedRun.workflowId} 和原 run_id 初始化。`
        : '请保留待人工核验项和检查点。',
    ].join('\n')
    try {
      const ok = inputActions.insertText(prompt, inputActions.captureInsertion()) === true
      setDraftFeedback(ok ? '已插入继续研究草稿。' : '草稿暂不可写入，请切回会话后重试。')
    } catch (error) { setDraftFeedback(error.message) }
  }
  return h('div', { className: 'rk-page', style: { padding: '20px var(--rk-gutter) 48px' } }, [
    h(PageHead, { key: 'head', title: '本次研究', lead: '查看当前任务、近期产出和待核验项。', actions: [
      h(Button, { key: 'project', size: 'sm', variant: 'ghost', onClick: openProjectEditor, 'aria-expanded': projectEditor !== null }, context.project ? `课题 · ${context.project}` : '研究课题'),
      h(Button, { key: 'refresh', size: 'sm', variant: 'ghost', onClick: refresh }, '刷新项目状态'),
    ] }),
    projectEditor !== null ? h(Card, { key: 'project-panel', style: { display: 'grid', gap: 8, marginBottom: 12 } }, [
      h('form', { key: 'project', className: 'rk-compose-actions', onSubmit: event => {
        event.preventDefault()
        setResearchProject(projectEditor)
        setProjectEditor(null)
      } }, [
        h(Input, { key: 'name', value: projectEditor, onChange: setProjectEditor, ariaLabel: '研究课题名称', placeholder: '留空使用默认课题', maxLength: 100, style: { width: 'min(260px, 100%)' } }),
        h(Button, { key: 'save', type: 'submit', size: 'sm' }, '切换课题'),
      ]),
      h('small', { key: 'hint', style: { color: C.muted } }, '按课题查看已保存的资料、证据与论断。'),
      h('details', { key: 'run' }, [
        h('summary', { key: 'label', style: { cursor: 'pointer', color: C.muted, fontSize: 12 } }, '载入已有研究运行'),
        h('form', { key: 'form', className: 'rk-compose-actions', style: { marginTop: 8 }, onSubmit: bindRun }, [
          h(Input, { key: 'id', value: externalRunId, onChange: setExternalRunId, ariaLabel: '研究运行 ID', placeholder: '填写运行 ID', maxLength: 120, style: { width: 'min(260px, 100%)' } }),
          h(Button, { key: 'bind', type: 'submit', size: 'sm', disabled: runAction || !externalRunId.trim() }, '载入运行'),
        ]),
      ]),
    ]) : null,
    runFeedback ? h(Notice, { key: 'run-feedback', tone: 'warn', style: { marginBottom: 12 } }, runFeedback) : null,
    error ? h(Notice, { key: 'error', tone: 'warn' }, `${error}。可刷新重试；离线数据不代表最新审核状态。`) : null,
    h(Card, { key: 'tasks', style: { display: 'flex', gap: 10, flexWrap: 'wrap', marginBottom: 12 } }, [
      h(Button, { key: 'review', variant: 'primary', onClick: () => onNavigate('catalog', { workflowId: 'literature-review' }) }, '做文献综述'),
      h(Button, { key: 'paper', onClick: () => onNavigate('catalog', { workflowId: 'review-paper' }) }, '审阅论文'),
      h(Button, { key: 'claims', onClick: () => onNavigate('vault', { tab: 'claims' }) }, '验证研究结论'),
      h(Button, { key: 'continue', disabled: !recentRun, onClick: () => restore(recentRun.id) }, '继续上次工作流'),
      activeRunId && supportsSafeInsert(inputActions) ? h(Button, { key: 'continue-draft', onClick: prepareContinuation }, '写入继续研究草稿') : null,
      draftFeedback ? h('span', { key: 'draft-feedback', role: 'status' }, draftFeedback) : null,
    ]),
    insertMaterialReference ? h(ResearchMaterialReferenceForm, { key: 'materials', insert: insertMaterialReference }) : null,
    projectRuns.length > 1 ? h('label', { key: 'run-picker', style: { display: 'block', marginBottom: 12 } }, [
      '恢复指定运行 ',
      h('select', { key: 'select', value: activeRunId, onChange: event => restore(event.target.value), 'aria-label': '恢复指定运行' }, [
        h('option', { key: 'none', value: '', disabled: true }, '选择运行'),
        ...projectRuns.map(item => h('option', { key: item.id, value: item.id },
          `${item.workflowName || item.workflowId || '研究运行'} · ${new Date(item.createdAt || 0).toLocaleString()} · ${item.id}`)),
      ]),
    ]) : null,
    !data ? h(Spinner, { key: 'loading', text: '正在读取项目进度……' }) : h('div', { key: 'content', className: 'rk-research-home-grid' }, [
      h(Card, { key: 'progress', style: { display: 'grid', gap: 8 } }, [
        h('strong', { key: 'question' }, question ? `研究问题：${question}` : '研究问题尚未登记'),
        h('span', { key: 'run' }, scopedRun ? `当前工作流：${scopedRun.workflowName || scopedRun.workflowId} · ${HOME_RUN_LABELS[scopedRun.status] || scopedRun.status}` : activeRunId ? `当前运行：${activeRunId}` : '还没有启动研究工作流'),
        overview?.current_stage && overview.current_stage !== 'unknown'
          ? h('span', { key: 'stage' }, `当前阶段：${overview.current_stage}`) : null,
        scopedRun && itemById(scopedRun.workflowId)?.requiresFiles ? h(Notice, { key: 'materials', tone: 'warn' }, '此工作流需要材料：请核对当前会话的 @文件 引用。') : null,
        scopedRun ? h('small', { key: 'boundary', style: { color: C.muted } }, '执行情况见运行记录和人工审批。') : null,
      ]),
      h(Card, { key: 'inbox', style: { display: 'grid', gap: 8 } }, [
        h('strong', { key: 'title' }, '待办收件箱'),
        h('span', { key: 'counts' }, `待核验 Claim ${pending} · 项目未核验证据 ${data.counts.unverified || 0}`),
        h('div', { key: 'buttons', style: { display: 'flex', gap: 8, flexWrap: 'wrap' } }, [
          h(Button, { key: 'review', size: 'sm', onClick: () => onNavigate('vault', { tab: 'claims' }) }, '处理 Claim'),
          h(Button, { key: 'evidence', size: 'sm', onClick: () => onNavigate('vault', { tab: 'evidence' }) }, '打开证据与筛选队列'),
        ]),
        data.missing.size ? h(Notice, { key: 'missing', tone: 'warn' }, `${data.missing.size} 条已关联证据在当前项目中缺失。`) : null,
        scopedClaims.some(claim => !claim.links?.length) ? h('span', { key: 'unlinked' },
          `${scopedClaims.filter(claim => !claim.links?.length).length} 条论断尚未关联证据`) : null,
        ...pendingStages.map(stage => h('div', { key: stage, className: 'rk-compose-actions' }, [
          h('span', { key: 'label' }, `待确认阶段 · ${stage}`),
          h(Button, { key: 'approve', size: 'sm', disabled: runAction, onClick: () => approveStage(stage), 'aria-label': `确认阶段 ${stage}` }, '确认'),
        ])),
      ]),
      h(Card, { key: 'outputs', style: { display: 'grid', gap: 8 } }, [
        h('strong', { key: 'title' }, `最近产出 · 已保存证据 ${data.counts.all}`),
        ...activityOutputs.slice(0, 3).map(item => h('span', { key: `tool-${item.id}` }, item.summary || item.kind)),
        ...(outputs.length ? outputs.map(output => h('span', { key: output.id }, `${output.title} · ${output.state === 'verified-execution' ? '执行已核验' : '草稿／执行待核对'}`)) : activityOutputs.length ? [] : [h('span', { key: 'empty', style: { color: C.muted } }, '暂无已登记产出。可在证据库记录图表、报告与复现信息。')]),
      ]),
    ]),
  ])
}


function ResearchSessionOverview({ sessionId = '' }) {
  const [context, setContext] = React.useState(currentResearchContext)
  const [summary, setSummary] = React.useState(null)
  React.useEffect(() => subscribeResearchContext(setContext), [])
  const run = sessionId && listResearchRuns({ project: context.project, sessionId })[0]
  const runId = run?.id
  const project = run?.project
  React.useEffect(() => {
    if (!runId) return undefined
    let alive = true
    synchronizeResearchClaims(evidenceVaultStore(), project)
      .then(({ claims }) => {
        if (alive) setSummary({ runId, pending: claims.filter(claim =>
          claim.run_id === runId && !['verified', 'rejected'].includes(claim.state)).length })
      })
      .catch(() => { if (alive) setSummary({ runId, pending: null }) })
    return () => { alive = false }
  }, [project, runId])
  if (!runId) return null
  return h('div', { style: { display: 'grid', gap: 4 } }, [
    h('strong', { key: 'project' }, project || '未命名项目'),
    h('span', { key: 'run' }, run.workflowName || run.workflowId),
    summary?.runId === runId ? h('span', { key: 'pending' },
      summary.pending === null ? '审核状态暂不可达' : `待审核论断 ${summary.pending}`) : null,
  ])
}

